-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = LegionChineseDB
D.Strings[117445]="就算在这个艰困的时局中被号召前来打击邪恶，你必须永远记住，帮助别人才会真正地让你与众不同。同情心，耐心与勇气就是圣骑士作战时的最大力量。$B$B清楚地了解这个道理，永远也不要忘记。"
D.Strings[117446]="免责声明。  试飞员对使用风动电容器（以下简称“设备”）的过程中可能引发的粉碎性骨折、触电身亡、重要器官损伤、被当地野兽吞食、时间和/或空间幻觉等致伤、致残或者死亡事件表示完全理解。试飞员自愿进入设备，并自愿承担上述风险。  试飞员同意，如果$g他:她;不幸罹难，将免除并永远放弃对塔利·萨普纳波及其家人提起诉讼的权利；并同意将$g他:她;的遗体捐献给萨普纳波进行研究。  签名： ___$n"
D.Strings[117447]="您好，学有所成的安拓维奇：$B$B 我希望你能在萨尔玛收到这封信，并且对你的研究有所帮助。虽然我还是希望能回到幽暗城，因为那边有全面性的工具与仆人可以协助我，但是我在断脊氏族的关系已经足以应付我的实验。$B$B 啊，死者的挽歌。$B$B 顺道一提，我有一些有趣的消息---$N从地狱兽人身体上采集的血液出现了恶魔腐化的浓缩体。这几乎与原来艾泽拉斯上受到恶魔腐化的地狱兽人完全相同……玛诺洛斯的腐化之血。$B$B 玛诺洛斯的影响不可能来到外域，这个地狱领主已经死了好几年了，但是，我担心有另外一个地狱领主正在此地肆虐。一个有着玛诺洛斯力量的地狱领主……一个可以腐化本地兽人的存在。$B$B 我会继续我对血之谷鲜血的研究，但是我极需你去追捕那个目标。我害怕这个目标将会引导你深入地狱火堡垒。$B$B 你勤奋好学的，$B 药剂师艾柏瑞克"
D.Strings[117448]="$N，  诅咒密码事实上是一组十分强大的咒文。它代表着古老的混沌力量，我们的世界那边的多起重大惨剧都与这组密码有关。是的，这也就是说，它并非是德拉诺所独有的。$B$B这个燃烧着的火焰符号代表凯尔萨斯，他渊博的古文知识可以完全理解这一切。$B$B你的发现已经惊动了纳鲁，阿达尔邀请你前往沙塔斯城与他会面。请你立刻到这里来，我们可以在圣光广场会面。  你谦恭的朋友，  卡德加"
D.Strings[117449]="安拓维奇，$B$B 首先，让我们来说说你上一个派来的人，$n，$g他:她;在工作上的表现已经远超过我的预期了。我已经占据了$g他:她;的身体，并且用$g他:她;的手来写这封信。这对我来说是多大的享受啊，我希望有一天我能有幸占据你的身体，强大的巫医!$B$B 所以，你要求我所做的报告如下：在地狱火堡垒内肆虐的恶魔比我过去遭遇过的强大许多。我猜想在第三次大战时着名的地狱领主玛诺洛斯就掌握了同样的力量，但拥有这股力量的生物屈指可数。然而，我感觉到有一股禁锢之风围绕着这个恶魔。如果它做出了违背其意愿的事情，我一点都不会感到惊讶，也许他是被囚禁或是在更强大的力量控制之下。$B$B 时间会证明一切的…………"
D.Strings[117450]="在地狱火堡垒的高墙内，我也感觉到命运的移转，就像他们说的一样，时间会证明一切。$B$B 你将会在此见识到恶魔的面容，来自艾泽拉斯的外来者，那里的繁茂生机，对于我来说就像是充满圣光与生命的地狱。如果你能允许我用比喻的话，你会明白在地狱火堡垒中的邪恶生物，只不过是巨大冰山的一角。$B$B 喔，在我面前的是一场多么荣耀的战斗啊!也许只有我可以品尝到即将被执行的痛苦与恐怖!$B$B 呃，我应该结束我们之间乏味的对话，并且让你慢慢想清楚以下的文字，亲爱的药剂师：你的身体可能是死的，安拓维奇，但是你的灵魂仍然十分完整，在你的防守发生失误，并且让我有机会接近你的那天，我应该啃食你的灵魂，并且在极佳的开胃菜搭配下，尽情的享用!如果必须的话，我会等到审判的第四天，但是，你会是我的!$B$B 晚安,$B -D"
D.Strings[117451]="自从你离开永恒树林后，我继续进行乌鸦圣典的研究，并发现一些有助于你打败乌鸦神的资讯。   解放这些灵魂已经将他们跟你绑束在一起，因此我认为他们可以自由的在对抗乌鸦神的战斗中提供他们的协助。   当你第一次解放灵魂时，他们将会处于休眠状态，因为他们几世纪以来都是如此。使用你的持续性疗愈法术，你可以以能量灌注他们，给予他们生命并在战斗中得到他们的协助。当魔法消退，他们将回复休眠状态。   接下来就是一系列我对每个鸟灵的注记:"
D.Strings[117452]="猎隼灵魂  猎隼灵魂充满了惊人的速度跟敏捷，在阿拉卡所关注的猎人技术当中受到高度的重视。如果你以持续性疗愈法术给予灵魂能量，它将赋予你于法术施放及近身战斗方面有一定程度的速度。"
D.Strings[117453]="战鹰灵魂  阿拉卡传统将战鹰灵魂配置得不似它的猎隼兄弟一样迅速，不过它所掌管却是狩猎中最高超的技术。如果你使用持续性疗愈法术使他从休眠中苏醒，战鹰灵魂将会使用它的技术来对抗你的敌人。   。"
D.Strings[117454]="猎鹰灵魂  石板上谈到很多有关猎鹰的事，好像他曾经是乌鸦的盟友。一个远古阿拉卡的复仇符号，猎鹰灵魂常常被罪恶的受害者召唤。使用持续性疗愈法术来唤醒这个灵魂将会使你能够分享它的力量，毁坏那些伤害你的人。"
D.Strings[117455]="以我们伟大主人之名……伊利丹大人万岁！  莫格霍尔：  我现在将这个废物派遣给你，让他在你那里继续为伊利丹大人效力。他没有成为死亡骑士的才能，不过，或许具备学习你那些能力的潜质。殴打他，羞辱他，去得到他的服从吧。让他成为一名真正的伊利达雷战士。  假如他失败了的话……那么一切都归咎于他自身的懦弱与愚蠢……那时候直接抛弃他好了。把他扔进深渊！  死亡骑士领主，塔隆·血魔"
D.Strings[117456]="不要绝望。你的特殊巨魔就在那里的某个地方。"
D.Strings[117457]="放下你的剑，你的槌，和你的矛。水晶告诉我们给和平一次机会。"
D.Strings[117458]="你不用怕一个满脑子啤酒的人!"
D.Strings[117459]="三个臭皮匠胜过一个诸葛亮!然后你就会永远都有朋友。"
D.Strings[117460]="智慧有很多种表现，但它永远源自水晶。"
D.Strings[117461]="正面点思考!一个人的垃圾会是另一个人的珍宝。"
D.Strings[117462]="你明天会遇到一个特别的人，所以记住:和蔼可亲会比拳打脚踢为你带来更多朋友。"
D.Strings[117463]="幸运号码: 13 9 17 4 n"
D.Strings[117464]="你跳舞的动作让大家脸上都浮现一抹微笑。"
D.Strings[117465]="你很特别，不管你的朋友，亲戚，同事，路上的陌生人，或是你的良心是怎么告诉你的"
D.Strings[117466]="当所有人都失败的时候，就是你大展身手的时候。"
D.Strings[117467]="酒醉就离天国不远了。"
D.Strings[117468]="警告:内脏不适人类食用。"
D.Strings[117469]="你被天空中最棒的金属之手选中!现在快去工作。"
D.Strings[117470]="让沉睡的古罗死去。"
D.Strings[117471]="这则讯息是欧格利拉开发委员会带给你的。加基森制造"
D.Strings[117472]="生命的意义是......(剩下的讯息意外地被吃掉了。)"
D.Strings[117473]="抱歉，这次你不是赢家。请再玩一次"
D.Strings[117474]="你今天会树敌，并立刻杀了它。"
D.Strings[117475]="寻找生命中更崇高的一条道路。在那条路上，你可以避开一些鄙恶之人"
D.Strings[117476]="以我们伟大主人之名……伊利丹大人万岁！  这些灵魂火炮的一般零件都是直接由各类工匠直接制造出来的。比如，技师和矿工能供应魔钢锭、氪金能量核心和精金框架给你。  但如果要想得到完美的奥术精华，就要去泰罗卡森林了。在森林中央那处部落据点裂石堡的上方有一面湖泊——尤鲁恩湖，你可以在那里找到一位名叫萨提斯的鸦人，他被放逐了，躲避在那里。  去和他谈谈，然后把你的需要告诉他。记得说明是我派你去的，因为他欠我不少东西，这么说肯定对你有所帮助。  之后，按照萨提斯说的去做，你就一定能得到精华。  - 巴塔斯"
D.Strings[117477]="在我的记忆中，利爪之王艾吉斯总是随身携带着泰罗克的羽毛。他将这羽毛视为自身王权的象征，或许还用来向他的追随者显示他就是泰罗克的转世。$B$B而我的兄弟黑暗编织者塞斯则一直戴着泰罗克的面具，领导着大厅内的塞泰克仪式。$B$B至于泰罗克的传说，则一直保存在利爪之王艾吉斯自己的房间旁边的一处宝库里，放置在数个符石组成的法阵中央。"
D.Strings[117478]="玛诺洛斯的影响范围没有那么大，绝对不可能达到外域。再说了，那只巨兽早就已经死了。所以，我认为这里恐怕还有其他的深渊领主，而且至少是玛诺洛斯那一级别的深渊领主……强大到足以腐蚀这里的兽人。  我会继续研究我手中的血环氏族血样，不过，我也建议你继续追究调查下去。根据我的推测，线索应该会将你领向地狱火堡垒的深处。  你睿智的顾问， 药剂师阿尔布雷克"
D.Strings[117479]="听着，霸德!$B$B这是最後一个我送去给你的傻瓜，除非你把欠债付清。$B$B不准再拖延了!$B$B格利夫塔"
D.Strings[117480]="加尔恩，$B$B我应该不需要提醒你，你的任务有多重要 -- 不计代价保护你珍贵的货物。如我所承诺过，成功与谨慎将会获得财富的回报。$B$B别对你的「夥伴」饶舌，看紧那些船员，那一切都会很顺利。我等着你成功的消息。"
D.Strings[117481]="我送去了一批可观的武力给你，长老，但你一定要小心注意你的活动。你的首要目标就是终止联盟对我们土地的扩张。某些为数不少的人类已经开始在贫瘠之地的边境上构筑一个巨大建筑物。$B$B一定要让他们知道自己在可悲的塞拉摩边界之外并不受欢迎。最後，告诫你一句话，长老:别让你的计画给蕨墙村的那些巨魔知道。那些野蛮的东西连最低程度的谨慎都办不到。$B$B - 亚加席姆"
D.Strings[117482]="我这辈子亲眼看过最可怕的生物就是泰瑟尔。我只看过那个怪物一次，我想我是真的够幸运才能活下来!$B$B那是个黑暗而且风暴肆虐的夜晚。大海翻腾，暴雨交加，塞拉摩灯塔的光线几乎看不见。我们尽力地往灯塔前进，突然间，那只恶兽就从波涛间冲向我们的船只!"
D.Strings[117483]="这个强大的生物张开血盆大口，向我们的船吐出冰弹，可怕的爪子抓住船弦，把船往山上撞击，水手和货物都被震到了海里，船也被撞成碎片，$B$B我能记得的最后一件事就是从断裂的船体里飞出来，掉到了海水中，被海浪淹没，世界变成漆黑一片，我想我就这么玩完了。当我醒来的时候，我正躺在塞拉摩的医务室里，我知道得有人把我们的经历讲出来。$B"
D.Strings[117484]="那个强大的怪物张开牠的血盆大口，对我们的船舰喷出冰冷的水箭。牠恐怖的大嘴一咬就把船头给咬了下来，扯裂了船体。水手与货物被猛力地甩离船，船只的残骸接着就被波涛所吞没。$B$B我记得的最後一件事，就是从破裂的船身上腾飞出去，接着摔进漆黑的大海中，在大浪间载沉载浮。世界逐渐变得黑暗，我想我咽下了我最後一口气。等我在塞拉摩的医院醒来时，我知道有人得说出我们的故事。"
D.Strings[117485]="小孩:乔艾与吉娜。妻子:苏珊娜"
D.Strings[117486]="刻在箱子侧的是预言符文…"
D.Strings[117487]="不要在我的坟茔上落泪。$B我不在那里，我也不入土长眠。$B$B我伴着群风飞舞狂啸，$B拂过北裂境的晶白霜雪。$B$B我是和煦的细雨，$B落在西部荒野的金黄麦田上。$B$B我是清晨的静默，$B漾在荆棘谷的丛林与绿蔓间。$B$B我在壮盛喧天的战鼓声中，$B伴着雷鸣般的蹄踏横跨纳葛兰。$B$B我是闪着温暖微光的繁星，$B散落在达纳苏斯的柔软梦境。$B$B我在鸣禽的宛啭之间，$B我在一切的美好之中。$B$B不要在我的坟茔上落泪，$B我不在那里。我也没有死去。"
D.Strings[117488]="<HTML>$B<BODY>$B$B$B<P>好吧，$N，这张清单列出了我们最新的超级机密，呃…超级武器所需要的一切东西。目前，就先叫它「卡芙缇的超进阶初体版微缩光束枪」吧。"
D.Strings[117489]="<HTML>$B<BODY>$B$B$B<H1 align=\"center\">我的工具"
D.Strings[117490]="<HTML>$B<BODY>$B$B$B<H1 align=\"center\">过载电容器"
D.Strings[117491]="<HTML>$B<BODY>$B$B$B<H1 align=\"center\">一把洛克那尔的砂粒"
D.Strings[117492]="第一班，第七钟$B又一次在兰姆酒柜找到赛卓克。 惩处。"
D.Strings[117493]="第一班，第八钟$B交班。一切平安。"
D.Strings[117494]="午夜班，第一钟$B赛卓克被发现想要打破船长的红酒柜。 惩处。"
D.Strings[117495]="午夜班，第二钟$B赛卓克在爬索具时被缠住并且摔了下来。 经过船医的处理後。 被送下去清醒。"
D.Strings[117496]="午夜班，第四钟$B在赛卓克的裤子里找到一瓶兰姆酒。 惩处。"
D.Strings[117497]="午夜班，第五钟$B找到了赛卓克的衣服。赛卓克被找到。赛卓克被惩罚。"
D.Strings[117498]="午夜班，第六钟$B赛卓克大声唱歌。吵醒了船长。赛卓克被船长惩罚。"
D.Strings[117499]="午夜班，第八钟$B交班。一切平静。两个人被派去找赛卓克。"
D.Strings[117500]="早班，第一钟$B船长室着火。所有人都被惊醒。火药被丢下船。"
D.Strings[117501]="元素之怒号角的传说在许久以前就在坦卡族的营火边被传颂着。每一代的战士听着这些故事长大，然後徒劳无功地寻找这个号角。伟大的风暴之蹄曾发誓要找回那个号角，抛下了他的村庄与家族。$B$B风暴之蹄勇敢地面对霜刃峰上那些冰冷残酷的元素生物，他独自登上那座山峰。登上了顶峰之後，风暴之蹄受到北风精灵本人的欢迎。在了解到北风不会轻易放弃那个号角之後，这个伟大的战士提出了挑战。"
D.Strings[117502]="风暴之蹄和北风纠缠了整整五天。在第六天的破晓，他将北风逐出了霜刃峰并取得了号角。疲惫而受了伤，风暴之蹄离开山脉回到村庄。$B$B在他靠近家园的时候，北风精灵召集了一批低阶的元素攻击风暴之蹄。虚弱的战士无法抵抗这样的攻击，而北风精灵完成了它的复仇。它将号角摔成两半，藏在闪亮的珠子中并且交给两个强大的戈洛克酋长，作为权威的象徵。$B$B<原始的文件突兀地结束，但某人或许是驯风者巴拉，在底下做了一些补充。>$B$B接受了北风精灵的吩咐，这两个戈洛克酋长将这珍贵的圣物传给子孙。直到今天，号角的碎片依旧在汨惊酋长和波咽酋长手中。"
D.Strings[117503]="<HTML>$B<BODY>$B<H1 align=\"center\">悬赏:赫米特·奈辛瓦里"
D.Strings[117504]="元素领主的忠诚仆人，就是此时此刻。$B$B我们在黑暗中受苦太久了，等候着我们的时刻，服务我们的主人，追寻着终将来临的末日。现在，虽然拉格纳罗斯姑息的火焰燃亮了整个夜空，我们现在握有了利器，能大洪水掀起战争与混乱!$B$B炎魔如今被禁锢在我们的世界。他无法施展他全部的力量，但依旧令人畏惧。将和它同样令人畏惧的敌手带到这个世界来，他们的冲突将会掀起一场元素大战，带来我们所期待的末日。"
D.Strings[117505]="奈普图隆的部下中，有个名叫艾胡恩的强大冰霜领主。至今他仍在聚集力量要对拉格纳罗斯掀起战争。他只需要一个通道来进入我们的世界；一个由我们提供的通道。我们有盟友，有地点。我们也有力量与意志。$B$B和我们忠诚的新盟友与客人之间的最後协商，将会在一个安全遥远的地方，在我们梣谷原始据点的西北边。$B$B在这个无知的「节庆」结束前，艾胡恩将会在黑石山的深处面对拉格纳罗斯。这个世界将会因为他们释放出来的力量而倾覆。$B$B我们一切的努力都是为了这一刻。我们的主人将会再次兴起，彼此征战，并且将艾泽拉斯撕裂成碎片。$B$B我们将会活在时间的终结，我的兄弟。肩负起你的任务。努力下去。我们终将获胜!"
D.Strings[117506]="戈拉莫什，$B$B我派了一位以太皇族代表去找你。戴辛大使告诉我他还有更多同胞想加入我们的行动。摸清他的底细，看看你能不能利用他。$B$B如果他派的上用场，我可以考虑让他的同胞加入。$B$B不要耍蠢;读完这封信之後记得烧掉!$B$BM"
D.Strings[117507]="(兽人语)部落的荣耀!不胜即亡 - 就是这几个字让我跟部落连结在一起!对任何一个部落的战士而言，这几个字是最神圣且基本的真理。$B$B我将我的血肉无条件献给大酋长，我将完成所有大酋长的意志，我就是大酋长命令下的武器。$B$B从此刻起我活着，直到世界末日英勇赴死 - 为了部落!"
D.Strings[117508]="$N，$B$B如果你正在读这封信，那就代表你还好好的活着 - 或者至少还有眼睛可用。$B$B我必须为这样保密致歉。阿格玛要求每封信件再寄出之前都要先被读过一遍 - 那里有太多的叛徒和窃贼了，相信你从悬赏布告上也看得出来。这里面有许多棘手的事情，新来的警卫很可能会误会。$B$B对一个部落的士兵而言，失败是绝对的。失败代表了死亡，而死亡没有丝毫交涉或诠释的空间。他们只能够冀望至少能光荣的死去。"
D.Strings[117509]="但胜利…胜利有许多不同的意义。也许你已经注意到了，柯尔克隆先锋全军到齐。大酋长派了他的菁英守卫来北裂境协助取胜。他们，以及你、和其他的英雄们，正把巫妖王和他的军队推向不可避免的终局。你每克服一项挑战，我们就更靠近从世上驱逐阿萨斯和天谴军团一步。$B$B但这就是我们两难的局面。因为我们在北裂境的作战是由年轻的地狱吼所主导。每一次的胜利都让此地的部落军队士气高涨，然後传遍全艾泽拉斯。"
D.Strings[117510]="不幸的是，地狱吼使用的是如此野蛮的战术。随着胜利渐近，地狱吼更加有理由认为他的方法是好的，而这将我们带向了我们许多年都未曾接近的东西:黑暗。$B$B我已经派了我的儿子去指挥我们在愤怒之门的部队。我知道他会光荣地作战，而且我希望我们的部队会注意到他的勇气与不屈不挠，并且向他学习。他在我不能亲临的地方展现我的心灵与力量…我希望你能够当我的耳目。我们能够一起把这件事正确地做好。$B$B鲜血与雷霆…愿你的到来能够将两者带给牠们。$B$B萨鲁法尔"
D.Strings[117511]="我们一切的努力都是为了这一刻。我们的主人将会再次兴起，彼此征战，并且将艾泽拉斯撕裂成碎片。$B$B我们将会活在时间的终结，我的兄弟。肩负起你的任务。努力下去。我们终将获胜!"
D.Strings[117512]="吾后，$B$B我们发现月眠花园的地脉交会点被蓝龙军团挖开了。他们的部队使用一种极涛磁针来破坏顶石，但没有将能量导回奥核之心，反而利用了一连串的聚焦点粗略地将能量从地下导向苍蓝龙殿。$B$B不用说，不管这魔法从哪里喷出地面都会造成严重的後果。林地古树、卡鲁耶克族，还有这个区域的其他生物都已经受到了不良的影响。幸亏，站在你面前的$r，$N，在追踪和处理这些问题的过程中帮了很大的忙。$B$B在我看来，$N对龙眠神殿而言是个很用的人才，能够帮忙处理神殿现在所面对的问题。我谦卑地请求你将$g他:她;当作我所找到的无价之宝。$B$B你诚挚的，$B$B莫德菈$B大法师，六人议会成员"
D.Strings[117513]="吾后，$B$B我们发现月眠花园的地脉交会点被蓝龙军团挖开了。他们的部队使用一种极涛磁针来破坏顶石，但没有将能量导回奥核之心，反而利用了一连串的聚焦点粗略地将能量从地下导向苍蓝龙殿。$B$B不用说，不管这魔法从哪里喷出地面都会造成严重的後果。林地古树、卡鲁耶克族，还有这个区域的其他生物都已经受到了不良的影响。幸亏，站在你面前的$r，$N，在追踪和处理这些问题的过程中帮了很大的忙。$B$B在我看来，$N对龙眠神殿而言是个很用的人才，能够帮忙处理神殿现在所面对的问题。我谦卑地请求你将$g他:她;当作我所找到的合适帮手。$B$B你诚挚的，$B$B埃萨·夺日者$B大法师，六人议会成员"
D.Strings[117514]="嗨!$B$B我不太擅长写信，所以监护员帮我写信给你。我只是想跟你说谢谢。因为你是个英雄，也许有天我也能像你这样拯救人们。$B$B好啦，我要去外头玩了。再次谢谢你这麽善良这麽强，你也是最$g帅:美;的!$B$B--你的秘密仰慕者"
D.Strings[117515]="雅图莎安静地蹑足通过巨大的地底隧道，紧张地回头张望，提防快速移动的轨道车。「他到底在哪…」她生气地低语，然後因为感觉到背後有东西在移动而猛然停下脚步。当她从鞘中抽出匕首的时候危险地眯起了双眼。$B$B一个嘶哑的声音在空房间中回响，「我还以为盗贼都喜欢待在目标的背後。」她快速转身，匕首戳上一个无法击穿的护盾。「我也以为圣骑士应该都是很贞洁的。」她带着自信的微笑回答。"
D.Strings[117516]="她一面倾身向前，一面大声数到隐形的泡泡随着一声破裂声消散为止。「十二秒?我知道你还有别种能力可以撑得比这更久。」$B$B纤瘦如骨的手指毫无窒碍地在他的盔甲下游动，松开胸甲，将他的胸膛暴露在寒冷的空气中。「别担心，我亲爱的马库斯，这可不是今晚的终结技…我才正要开始呢。」他用手臂环绕着她剩余的腰部，轻啮她的颈椎，挤得她咯咯笑。$B$B<这本书剩下的段落因为反覆阅读而磨得看不清楚了。>"
D.Strings[117517]="<HTML>$B<BODY>$B<H1 align=\"center\">大将军阿比迪斯的日记"
D.Strings[117518]="表格内容$B$B第1章 - 亡灵与你$B$B第2章 - 维持食屍鬼外型:七种简易运动$B$B第3章 - 保持冷静:挑选一个合适的棺材$B$B第4章 - 墓地保证书: 五十种爱的签名保证$B$B<整本书非常完整，看起来完全没有被读过>"
D.Strings[117519]="<HTML>$B<BODY>$B$B$B<H1 align=\"center\">大将军阿比迪斯的日记"
D.Strings[117520]="<HTML>$B<BODY>$B$B$B<P>那个声音低语，「到我这儿来……」从一开始我就知道那是圣光在我的梦中对我说话。终於!在我这些年的祈祷与善行，清除那些在艾泽拉斯地面上的不死生物与瘟疫。在所有的失败与复苏之後。"
D.Strings[117521]="<HTML>$B<BODY>$B$B$B<P>又再此发生了。「到我这儿来……」圣光命令我。"
D.Strings[117522]="<HTML>$B<BODY>$B$B$B<P>这一次我醒了!充满活力，但过了大约一分钟之後，在这温暖阳光普照的日子里，我吐出的气息化成白雾而冰冷。有一个牧师注意到，开始屈膝祈祷。"
D.Strings[117523]="<HTML>$B<BODY>$B$B$B<P>指挥官和主教都接受了。他们并非全无选择。史曲特主教显得尤其热心。他提到十字军的再起，并且发誓要把我们之中的信仰不坚全赶出去。"
D.Strings[117524]="<HTML>$B<BODY>$B$B$B<P>我把多数的十字军留在这里继续处理我们後院的不死生物。我想像着一旦他们完成了我们起头的事情，他们就能解甲归田，回到家乡平静度日。"
D.Strings[117525]="<HTML>$B<BODY>$B$B$B<P>人们开始谈论即将到来的一天，将会改变血色十字军的每一件事。史曲特主教替它取了个名字，叫做赤红黎明。"
D.Strings[117526]="<HTML>$B<BODY>$B$B$B<P>圣光又迫切地对再次对我说话了。我带着不耐的情绪从睡梦中醒来。我不会让圣光失望的。绝不能再拖延了。我们一定得尽快上路!"
D.Strings[117527]="<HTML>$B<BODY>$B$B$B<P>现在我知道为什麽圣光挑选我来进行。有一天夜里一个天谴亡域飞过我们头上的空中，并且释放出地狱的爪牙!"
D.Strings[117528]="<HTML>$B<BODY>$B$B$B<P>有人通知我壁炉谷和附近的地区已经开始在集结了。高阶指挥官嘉尔瓦·波尔伯勒自己打算离开他们来拯救我们。他的努力是无用的。"
D.Strings[117529]="献给瓦里安·乌瑞恩$B某些人口中的洛戈许「鬼魂之狼」$B$B在多年的流放後他奇蹟般的归来，这些流浪与艰困反而点燃了他对联盟的精神和勇气。$B$B我们要勇敢地进入这些危险之地，在心中效仿他的英勇与顽强。$B$B$B-大领主伯瓦尔·弗塔根"
D.Strings[117530]="第1天:那些人类垃圾看来很高兴，丝毫没有注意到我的存在，毫不意外。他们已经是俎上肉，就等着被轰炸，要我标出他们的位置只是迟早的问题罢了。$B$B第2天:绘制完毕 - 对我如此完美的男人来讲，真是个不重要的工作。为什麽我得做这种事 - 他们应该叫J-Y C.来做这个。他说话时的可笑口音就足以构成派他来的理由。$B$B第3天:第一口气终於开始变得有点浊了。或许我应该在这几天内浮向水面再吸一口气。依旧无聊得要死 - 那个该死的接应信号在哪里?<持续的抱怨……>"
D.Strings[117531]="第12天:啊，松了一口气的感觉真是愉快。第二口气尝起来像是我所尝过最纯净的孤儿眼泪。信号依旧没有出现，令人费解。而我可以发誓有只螃蟹试图拿我的脚指当成鼓来敲。$B$B<嚷嚷变得越来越没有意义……>"
D.Strings[117532]="第36天: 第三口气终於用完，我左手肘的血管在上来的时候又一次充满了泡泡。螃蟹发出的鼓声如今是我不变的伴侣，是我窄小黑暗地狱的打击乐背景音。很显然地，我被那些卑鄙的家伙们给忘了。如果今天是J-Y在这里，他们才不会忘记他!他们也不会把汉斯或西薇雅丢下!为什麽会忘记我?$B$B<句子在沮丧的涂鸦中结束……>"
D.Strings[117533]="给大将军阿比迪斯$B新亚法隆，血色大地$B$B大将军阿比迪斯，$B$B我希望信能平安寄到你手上。我的名字是丹赛尔·亚当斯，我从事猎人的行业，但却流着血色十字军的血。我写这封信给你是因为我见证了一个奇蹟。"
D.Strings[117534]="当我例行性地净化那些出没在病木林的天谴军团时，我和队伍被一阵来自天空，震耳欲聋的尖叫所打断。我们抬起头望向天空，看着纳克萨玛斯，我们的下巴几乎都要掉到地上了。我现在告诉你，大将军，那是个令人无法置信的景象!惊惧城塞正在移动。一开始很慢，但後发出一阵打雷般的轰声 - 然後就这样子不见了!$B$B没错，大将军，纳克萨玛斯消失了!没了!这难道不是圣光的奇蹟吗?我说一定是!"
D.Strings[117535]="愿那些不洁、肮脏的野蛮人受到审判。赞扬圣光!$B$B让我们的兄弟姊妹知道这个奇蹟，大将军。$B$B愿圣光永远地保护你，让你可以传播那些善言直到世界终结。$B$B满怀敬意的，$B$B丹·亚当斯$B结尾"
D.Strings[117536]="1. 留出一蓬胡须，因为这可以掩饰面对圣光时的不完美。$B$B2. 以母马的马奶洁净你的双手，在奉献时的双手应该柔软而滑顺。$B$B3. 在河中沐浴，让圣光荣耀的自然礼赞清洁你的皮肤。"
D.Strings[117537]="4. 换下你日常的圣袍，让你的外观和气味不会触怒圣光的仆人。$B$B5. 随时随地都维持挺直的姿势 - 不要让疲劳或懒散使你的脊椎弯下。$B$B<清单後续还有好几页的注意事项>"
D.Strings[117538]="从高阶修士兰格瑞的桌上:$B$B在黑暗时刻的混乱与斗争中，一个人好像应该转向内，保护自己的家人和所爱，排除其他的。但这种想法是错的 - 没有教会这样的希望灯塔，绝望会在你家人的灵魂中泛滥。吃饱、穿暖和快乐的笑容，这些世俗好事的追求无法拯救你家人心中的空虚，劝你不要逃避对圣光的职责。"
D.Strings[117539]="交付给教会。在世俗享受匮乏时的艰苦忍耐就像是灵魂的熔炉，能够烧去一切的不纯净，将你提升到更高的层次。不要因为肚子饿得咕咕叫，赤着脚被尖石割伤，或因为寒风在颤抖而感到羞愧。这只是圣光对灵魂的激励与考验。这些牺牲确保那些献给圣光高入穹顶、映着金光的颂歌能够激励你的信仰。$B$B弃绝肉体的享受，而圣光就靠你越近。"
D.Strings[117540]="放纵沉溺的主题是很困难的，但在我们的生活中，这是必要之恶。小小的背离正义，脱口而出的粗话，愤怒时的拳打脚踢 - 这些所有事情都会使一个人衰弱，而教会必需要确认这一切。$B$B然而，这样的确认并非毫无代价。粗话的罪行可能只需要一些银币就能净化你的灵魂。但是暴力的罪行就需要金币才行。至於其他的罪行，完全的坦承认罪，和慷慨的奉献都是必须的。"
D.Strings[117541]="殴打:$B殴打脸部: 2金币$B殴打下体: 3金币$B殴打胸膛: 1金币45银币$B $B<一份关於罪刑与价格，长达好几页的详细列表。>"
D.Strings[117542]="靠劳动来净化身体。靠祈祷来净化灵魂。靠火焰来净化敌人。疼痛不是你的敌人，而是值得拥抱的盟友，紧紧地拥抱它，传播给不信者与信者。$B$B抵抗圣光的道路是不洁的象徵，应该要将他的血肉割下。"
D.Strings[117543]="大将军，$B$B壁炉谷和提里斯法的军队只离新亚法隆不到一天的距离。我们飞驰而来，圣光在我们的背上闪耀，风在我们的马蹄间流转。很快地天谴军团就得对付血色十字军的全部力量!$B$B圣光祝福你，$B$B高阶指挥官嘉尔瓦·波尔伯勒"
D.Strings[117544]="<HTML>$B<BODY>$B$B$B<H1 align=\"center\">赎罪之途"
D.Strings[117545]="指挥官和主教都接受了。他们也没有其他选择。史曲特主教显得尤其热心。他提到一个全新的十字军，并且发誓要把我们之中的信仰不坚全赶出去。$B$B我要他别那麽激动，我们组成一个最虔诚的菁英集团前往北裂境去执行圣光的意志，并不是想摧毁十字军。我担心人们和乐卡夫的友谊会慢慢地扭曲他。他们各有用处。$B$B史曲特讲到一个新的十字军，但我也有我的考量。我想等我们召集了这一只部队之後，我会给我们一个新的名字。能够象徵我们的新任务，但依旧和过去有所关连。我会和高阶修士一起祈祷。"
D.Strings[117546]="<HTML>$B<BODY>$B$B$B<P>我们的祈祷获得了回应。高阶修士因为圣光之声的影响而动，再清楚明确不过了。"
D.Strings[117547]="<HTML>$B<BODY>$B$B$B<P>当我看着新亚法隆时，我感到一阵惊恐，我最後一次怀疑。我们的命运就在北裂境。因为某些理由我充满了一种不祥的预感。眼下的任务应该能让我不要继续胡思乱想。我将它们赶出我的脑袋。"
D.Strings[117548]="<HTML>$B<BODY>$B$B$B<P>今天早上没有从我的信差收到任何消息。显然他们都没能活着抵达壁炉谷。我们已经失去瘟疫之地了。波尔伯勒会带着他的部队往这里来，然後在开阔处遭到歼灭。"
D.Strings[117549]="<HTML>$B<BODY>$B$B$B<P>稍晚，兰格瑞告诉我他也看到了一样的启示。我无法理解为何圣光要求我们做出这麽不荣誉的事，但是我并没有资格质疑 - 我只能服从，而我将会服从。"
D.Strings[117550]="<HTML>$B<BODY>$B$B$B<P>如果运气好的话，高阶指挥官波尔伯勒将能够支撑住并且重整那些幸存者。我是个懦夫 - 夹着尾巴逃跑的败犬!"
D.Strings[117551]="<HTML>$B<BODY>$B$B$B<P>我有一段时间没有写日记了。我能做的就是尽量站直，不要继续不适下去。有人开始质疑为什麽我大部分的时间都躲在自己的房间中。但让他们看到我这个样子也对士气毫无帮助。"
D.Strings[117552]="<HTML>$B<BODY>$B$B$B<P>我们遭到毫无警告的攻击!乘着庞大长船的巨人像鬼魅般地从雾中出现!他们沉默得有如亡灵。"
D.Strings[117553]="<HTML>$B<BODY>$B$B$B<P>我今天早上在画满标记得地图堆中醒来。圣光引领着我的手，将我们的目标标示出来。"
D.Strings[117554]="<HTML>$B<BODY>$B<P>登陆了!"
D.Strings[117555]="<HTML>$B<BODY>$B$B$B<P>已经过了一个月，建设的速度十分地迅速。我忙得没空继续写日记。我的斥候告诉我这片土地充满了龙与其他奇怪的生物。我们要持续努力直到我们准备好。"
D.Strings[117556]="<HTML>$B<BODY>$B<P>今天晚上巴瑞恩·韦斯温上将出现在我房门前!许多的证据都显示他早在多年前就死在海上。"
D.Strings[117557]="<HTML>$B<BODY>$B<P>我们坐下来聊了一整夜，直到早上。他向我保证他并没有取代我的意图，但圣光引导他穿过大龙骨荒野，担任我的顾问和名义上的指挥官。他说北裂境将迎接巨大的改变。部落与联盟将会成群地来到此处，为了对抗巫妖王将施放在他们身上的巨型瘟疫。"
D.Strings[117558]="<HTML>$B<BODY>$B<P>人们以强烈的狂热跟随着上将，尤其是高阶修士兰格瑞和主教史曲特。显然高洁的圣光在上将睡着时对他诉说了新的祝福，而他告诉兰格瑞。很多人现在投身教士组织，现在被称为「乌鸦牧师」。"
D.Strings[117559]="<HTML>$B<BODY>$B<P>有些事情不太对劲。我没办法插手，但我也无法全然相信上将。他其实没做错什麽。恰恰相反，什麽都没做错!但我还是觉得要相信我的直觉。"
D.Strings[117560]="<HTML>$B<BODY>$B<P>又过了一两个月。我们在新壁炉谷的兴建有很大的进展。城墙和兵营几乎都已经完成了。卡列基的手下真是奇蹟般的工匠。"
D.Strings[117561]="<HTML>$B<BODY>$B<P>我的手下回报说有一小群被遗忘者在北方丘陵的半山腰开始建造营地。在丘陵的另一边，联盟则开始建造一个更大的基地。"
D.Strings[117562]="史寇札德紧张地盯着圆柱的周围。正如他所计画，他看见她漂浮在那儿，一个人在她的房间里。他的决定正确吗?深夜前往一个女妖的卧室?要是被发现的话，他肯定会被死灵法师埋回地下去。更糟的是，他根本不知道对方会怎麽回应他的心意，希德娜芮夫人的脾气可是以暴躁闻名。"
D.Strings[117563]="本来这殭屍还有点疑惑，但是当他看清她的美貌之後就通通抛诸脑後了。她清晰的精灵特徵 - 她过去人生的一点残存 - 在淌着液体的伤口和生着屍斑的脸庞上更加明显。泛紫而近乎透明的皮肤勉强地覆盖着她那被死灵能量所包裹拥抱的躯体。冰冷的血肉整洁地短暂融合，她没有脚的躯体就坐在蓝色的能量球体上，漂浮在冰冷的大理石地板的上空。史寇札德让自己放松了一些，抹去额头上的汗水与液体。"
D.Strings[117564]="很显然地并未注意到他的存在，女妖飘向房间唯一的窗户，看着外头的战场。荒芜随着她的视线延伸。不到六个小时之前，人类儿童的哭喊在空中回荡，但现在…只剩下死亡的甜美静默。"
D.Strings[117565]="风吹拂着她的长发，蛆虫般的纠结在她中空凹陷的眼窝旁摇曳舞动。史寇札德突然惊觉自己受情慾的吸引而靠得太前，他赶紧缩回柱子後面，害怕黑暗恸哭者会看见他。她的确看见他了 - 但他没有理由要害怕。"
D.Strings[117566]="「史寇札德，」她说。「我一直在等你。你今天在战斗的表现很不错。」女妖从她腐烂的右肩羞怯地瞥了他一眼，任由自己的屍衣缓缓地下滑。「你该来…领取奖赏了。」"
D.Strings[117567]="<後面的几页看来都黏在一起了。>"
D.Strings[117568]="『狂怒』塔提克。天谴军所创造出最强大的憎恶体之一。协助『寒冰使者』亚门纳尔在剃刀沼泽建立据点。塔提克曾经一个人宰掉超过1200只野猪人，直到他终於被击倒。他的牺牲提供了屍体让亚门纳尔能够迅速地召唤出一批不死野猪人大军，最後建立了天谴军团在卡林多的第一个据点。塔提克的某些残骸被用来制造暴食者，亚门纳尔的现任副官。"
D.Strings[117569]="欧布拉西姆，旅行者。天才建筑师，纳克萨玛斯的建构枢纽也是亚榭洛的幕後建造者。他很快地从骷髅劳工的位阶中晋升为科尔苏加德最信赖的顾问之一。$B$B欧布拉西姆总是以学者的身份在世界各地旅行，收集知识，他早期的灵感来自於奈幽虫族的建筑和兽人术士的魔法。他最後一次被看见是在好几年前，当时的他朝西而行，前往卡林多研究辛艾萨拉遗迹。"
D.Strings[117570]="『天谴者』迪奥多。人类死灵法师，诅咒神教的创始成员之一，也曾是第一次战争受勳的英雄。成功地领导了天谴军在第一次和第二次对血色修道院的夏季突袭中获得胜利。在第三次(也是最後一次)的夏季突袭中阵亡，因为血色十字军解开他的作战模式而被击败。"
D.Strings[117571]="『狂热』奇尔齐赞。一位直接隶属於巫妖王的强大巫妖。奇尔齐赞是个经历过无数战斗的老将，并且亲自规划与领导了血红攻势，那是对圣光之愿礼拜堂进行过最大规模的攻击之一。尽管获胜机率极高，但他的攻势还是被迅速地反击，他的部队也受到巨大的损伤。奇尔齐赞本人则是被麦斯威尔·泰罗索斯领主重创，连实体都无法维持。"
D.Strings[117572]="北裂境西部 - 来自空中监视中队於寒冰皇冠的报告，与巫妖领主冽冬的联络完全中断。「我们最後一次看见冽冬，他正控制着亡域塔尔拉玛斯，飞往北风冻原进行一个机密任务，」由天谴技师卡洛蒙，中队的首席情报官所回报。「根据我们的侦察判断他的通讯水晶应该能够正常运作…只是…一片死寂。」"
D.Strings[117573]="死亡止境，东部王国 - 讲师拉祖维斯在这周稍早时，重申了他对反叛和不服从的态度。「任何胆敢背弃天谴军团的死亡骑士将会遭到比死更惨的下场。他们的痛苦将永无终结 - 我会亲自监督这件事。」"
D.Strings[117574]="龙骨荒野 - 瓦拉纳尔亲王正要找一个特殊的死亡骑士前往龙骨荒野，北裂境寒冻的中央平原，并且率领一群核心的菁英士兵攻击红龙军团。「你们的训练即将完成，」他在最近几次公开演说中提到。「该是时候打击那些自以为的生灵保护者了!我们要让他们瞧瞧龙骨荒野的真正含意!」"
D.Strings[117575]="雅立史卓莎，红龙之后可以被视为天谴军团在北裂境最强大的敌人，她近来正在召集自己的军队，伪装成要对抗狂乱的蓝龙军团。"
D.Strings[117576]="幽暗城 - 我们在幽暗城的探子回报说部落正在动员准备进攻北裂境。「部落的军队，多数都是由外域调回来的部队，现在正在集结准备攻击寒冰皇冠。」"
D.Strings[117577]="更进一步，被遗忘者的皇家药剂师学会中的间谍回报，他们最近活动频繁。「虽然目前仍不确定，但谣言指出学会似乎在他们的瘟疫研究上有了突破。再次强调，只是谣传，但各处的部队都提供了被遗忘者链金师的位置。」"
D.Strings[117578]="亚榭洛的死亡骑士$B$B姓名:杰德$B状态:存$B评价:嗜血"
D.Strings[117579]="姓名:希赞$B状态:存$B评价:饶舌"
D.Strings[117580]="姓名:穆齐$B状态:存$B评价:深具破坏性"
D.Strings[117581]="姓名:科贝特$B状态:殁$B评价:自从死後就没什麽啼声。或许免於遭受一辈子的苦难。"
D.Strings[117582]="姓名:和谐$B状态:殁$B评价:这个死亡骑士的名字违反了天谴军的准则。由巫妖王亲手处死。"
D.Strings[117583]="姓名:缪特$B状态:存*$B评价:被转变为食屍鬼。"
D.Strings[117584]="姓名:米尔顿$B状态:存$B评价:鬼混。"
D.Strings[117585]="姓名:密妮塔莉丝$B状态:存$B评价:会看见不存在的东西。"
D.Strings[117586]="姓名:$N$B状态:存$B评价:需要更多磨练。$B$B<接下去还有数百页。>"
D.Strings[117587]="亚榭洛的死亡骑士$B$B姓名:杰德$B状态:存$B评价:无法抵挡。"
D.Strings[117588]="姓名:希赞$B状态:殁$B评价:张着嘴巴死去。"
D.Strings[117589]="姓名:穆齐$B状态:存$B评价:愤怒。仇恨。进展良好。"
D.Strings[117590]="姓名:缪特$B状态:殁$B评价:被转变为食屍鬼。被血色农民所杀。"
D.Strings[117591]="姓名:米尔顿$B状态:作战中失踪$B评价:胆小的地精。"
D.Strings[117592]="姓名:密妮塔莉丝$B状态:存$B评价:整天追蝴蝶。"
D.Strings[117593]="姓名:$N$B状态:存$B评价:亲手杀死了数百名的血色十字军。还渴望更多。$B$B<接下去还有数百页。>"
D.Strings[117594]="屍虫，亚榭洛的大厨，提供你美味的食物。他骄傲地喂养伟大的天谴军并让他们更强壮。可别惹火屍虫，否则他就不给你东西吃。$B$B守则:$B$B死亡骑士先吃，食屍鬼轮流等着吃。$B$B不准吃你旁边的食屍鬼。要先把盘子里的吃光光。$B$B可以把自己的蛆和虱子加到食物中。屍虫不在意。$B$B有寄生虫?拿来给屍虫!$B$B可以吃人类或精灵。精灵也算是一种白肉。"
D.Strings[117595]="弄乱了餐点，看见了餐巾让屍虫羞愧地垂下头。$B$B可以把还不够烂的食物带回来。屍虫有三个腋窝可以摆。$B$B可以用手或拿剑吃饭。但不准吃手或吃剑。$B$B殭屍要多吃一点。要用脑以外的地方吃东西。$B$B不要吃自己。"
D.Strings[117596]="冰霜巨龙复活说明$B$B笨重的骨头几乎被雪所掩埋，但谁也不会认错那些突出来的狰狞利爪，在严肃痛苦中扭曲的模样。死灵法师一语不发地聚集起来，在巨龙的屍体旁绕成一圈。他们站在那边直到卷着雪花的冷风将他们包围。接着仪式开始了。"
D.Strings[117597]="不洁的光芒从冰封的骸骨中散发出来，迅速地刷过积雪和结冰，直到巨大的遗骸完全暴露出来。随着大死灵领主安提欧克的一个手势，骸骨颤动着，突然地从地面上摇晃地站起，缓慢地在原地旋转。"
D.Strings[117598]="当死灵法师将知觉灌入怪物残骸时，他们的咒法也随之增强。腐化的重生与巨龙的意识征战，产生的激烈扭曲残害着牠的身躯。在一声尖细的叫声划破天空之後，怪兽屈服了。一股冰霜的光芒在牠空洞的肋骨中点燃，蔓延至四肢，为牠的双眼带来一股奇异的标志。"
D.Strings[117599]="大死灵领主往前走了一些说:\"巫妖王认为你应该被复活，为天谴军效力。你将成为死亡最高傲的武器，在敌人的村庄里降下苦难，以生灵为宴，成为我们最优秀的死亡骑士。\""
D.Strings[117600]="冰霜巨龙看着他们，微微地低下头表示服从。融合完成了。牠举起背，如同划破天空的刀刃，展开翅膀。"
D.Strings[117601]="有件事情引起了我的注意。有些新复活的死亡骑士被他们的前世记忆所困扰。我恳求这些烦躁的心灵别再担忧了，因为无人能够在他前世所犯下的错误之上超越我。然而，在天谴军，我仍获得赦罪。"
D.Strings[117602]="在无知之下，我曾经是信仰憎恶圣光的圣骑士。被希望的谎言所遮蔽，我留下了妻子与两个年幼的女儿，在我们的区域中寻找天谴军的踪迹。我们的小型部队在森林中旬找了数周，但每条小径却已冰冷。冬天来临，我们却对敌人一无所知。心灰意冷地转头回家。"
D.Strings[117603]="下山时，远处的景色令人生怖。村庄正在燃烧着，毁灭着。我跑回我们的屋子。一个假的门栓被弃置在一旁。当时我过於悲伤，没有多想，就冲进了屋子里，找到倒在我脚下的家人们，被火烧得难以辨认。我带着愤怒转身，看着他们在门上，惊慌时所留下来的抓痕。最轻的那些抓痕是最年幼的孩子的。"
D.Strings[117604]="我後来才知道，我们离开的那一阵子，瘟疫使者在村庄周围藏匿的谣言甚嚣尘上。血色十字军看着最後的一些居民被包围，活活烧死。我完全没有办法理解他们的残忍，直到我发觉现在心中熊熊的愤怒。我渴望猎杀这些十字军，让他们在我愤怒的刀刃底下受难。"
D.Strings[117605]="最终，我被迫跟其他人集合。我感受到我的绝望与愤怒，同时也有些其他人的，但领队命令我们前进到最近的残存路哨。在夜晚後不久，我们从树後听到不祥不死生物的格格笑声，接着一波天谴军突袭了我们。"
D.Strings[117606]="我毫无感情地杀着他们。但当一个倒下，就会有两个从山丘上爬下。我们被我们追击的天谴军所困住，但是现在我们四分五裂且毫无防备。我的同伴们一个一个因为伤口和精疲力尽而倒下。实在是有太多的天谴军了。"
D.Strings[117607]="当攻击来到时，我还记得在林子里跟我的女孩们嬉戏。为什麽这样的记忆还存在呢？这些东西都只是幻影，让我从绝望和痛苦的现实中分心。女孩们已经死了，村庄也被天谴军所践踏。死亡才是所有活着的生物的最终道路。由保护别人而产生的力量最终只会导向失败。成功只会在那些将力量用在其他事物上的人得证。"
D.Strings[117608]="接着在彼处，我向巫妖王宣示我的忠诚，他是这个时代的胜利信使。他从折磨我的人类感官中净化我。我重生而成了死亡骑士。我与我的兄弟们不会在其他力量下屈服。没有失败苦涩到能测试我寒冰般的决心。我被天谴军所净化，我也准备好在宽广的艾泽拉斯大陆上满足我对死亡的渴求。"
D.Strings[117609]="欢迎加入天谴军。既然你已经真正地服役了，你会发觉你从那些不便的各种凡人痛苦中解脱。没有扰人的睡眠偷走你的时间，不需避难所躲避各种天灾，甚至连剪指甲跟头发都省了!真愉快!"
D.Strings[117610]="不过，还是有几件无关紧要的事情需要注意，就是身为不死生物的注意事项:$B注意你的腐烂程度。有些可以让你吓唬敌人的当然很好，但是在战斗中突然掉下一只手臂可就难为情了。$B学着喜爱你的恶臭。有些人说很恶，我们说这才自然。$B闪开那些活着的动物，尤其是狗。"
D.Strings[117611]="留心你的失态。你要是敢把你的下颚放错，你可能会被重新分发到咯咯声都没有人听的到的地方。还有，那些有特别癖好的人。$B酒精现在不只是酒精了。对此致上我的歉意。$B每天用血洗一次澡可以把活人的气息洗掉(虽然会产生一些皱纹泡泡)。避免穿一些粉色系的衣服，他们跟你的颜色不搭。$B他们再也不会让你看起来很肥。"
D.Strings[117612]="时尚食屍鬼$B一本关於处理伤口与回收的手册"
D.Strings[117613]="包紮$B$B一个伤口一天会流血三次就应该要包紮。包紮用的绷带布料请依自己的喜好决定。许多食屍鬼偏好符文布，因为他们原本的紫色会在浸血之後变成病态的紫红色。当然你也不能忽略简单亚麻的高雅黄色，然而，实地试验是最重要的!"
D.Strings[117614]="屍斑与溃烂$B$B腐烂、化脓的伤口是目前最流行的外型，而且在转换心情上有着无比的妙用。但别让它停留在身上太久，尽管!未拆线的脓包可是个不可放过的机会。"
D.Strings[117615]="虫子$B$B噢，何不就把它们留着呢?它们吃得不多，它们在增进你苍白的仪态与令人难以抵抗的恶臭上有着令人惊叹的贡献。但如果你变成蜜蜂或黄蜂的殖民地，请尽快前往最近的屠宰场寻求协助。"
D.Strings[117616]="缺断的肢体$B$B在战斗中的混乱状况不适合更换失去的肢体。请确认你到底失去了多少肢体。只要一位侍僧有空去看照你，我们将会提供最适合的肢体。危急时，不要客气，从同僚身上借一只手吧!"
D.Strings[117617]="同类相食$B$B为了避免天谴军员工发生彼此吞食的情况，你不应该吞食任何倒在地上尚未超过5秒的东西!还有，侍僧的床铺并不算是地上!"
D.Strings[117618]="条目1:$B$B大将军的热情激起了农民的狂热!十字军的舰队每天都在增强，我们的人数也大幅成长。在我们的弓弦上有着一柄强大的武器等着攻击北裂境，让我们结束这无止尽的战斗。我们的处境艰困，但是。血色堡垒陷入火海，我无法不闻到身後死亡的气息。"
D.Strings[117619]="条目15:$B$B阿比迪斯失去了她的判断力。她试图在十字军中制造分裂，又只希望以一小群最虔诚的人攻击巫妖王的大本营!难道她打算放着新亚法隆和提尔之手陷入火海，然後她带着我们最後的防卫者航向世界的尽头?"
D.Strings[117620]="条目23:$B$B清晨十分的明亮，男男女女在矿坑和农地上工作，十字镐和锄头也随之闪闪发光。一道阴影降临 -- 一座亡域。这不是纳克萨玛斯。天谴军就在邻近处驻紮，而阿比迪斯下令要我们战到最後一人。难道我发誓忠诚只是为了要替阿比迪斯逃跑的时候殿後?"
D.Strings[117621]="<一张潦草画成的地图被夹在日记的最後一页。看来作者打算要游过罗德隆的东北海岸，在提里斯法林地上岸!>"
D.Strings[117622]="我警告过你们大部分的人，下一次的战役我花在清理靴子的时间比踢这些小鬼头还多，有人准备等死吧!从今天起清理马粪的时间要延长一倍，所有的魂屍都要参加!$B$B--讲师拉祖维斯"
D.Strings[117623]="看看这最讽刺之处。活着的人把自己人生中最病态之处归咎於不死 -- 绝望、奴役、野蛮，灵魂的停滞。但我们服侍!活着的人服侍国王，督军，德鲁伊，牧师，诸神，人和野兽。我们只服侍巫妖王伟大的意志，让我们繁盛而统一!"
D.Strings[117624]="所有人的努力，只留下无数的悲剧、残酷、背叛和自私的纪录。而天谴军团只有效率和整体。在活着的时候服侍巫妖王，或在死後服侍他。他替我们选择了圆满的道路!"
D.Strings[117625]="肉体感到冰冷，却因为团结而温暖。伟大的天谴军是一个国家，一个心智，一个存在。真正的寒冷是守卫在战争时，拒绝邻国生病难民的冷酷视线!难道所有的人不是一样的吗?不，因为他们结冰的心而有所区别。"
D.Strings[117626]="高高抬起我的理想，打倒我们的敌人!让那些被打倒的加入我们，直到所有人都服侍冰封王座!"
D.Strings[117627]="我终於赢得了理事会的青睐，获得进入通灵学院的许可!今天我终於可以踏入光荣的不死人生!"
D.Strings[117628]="通灵学院的生活比我期待更粗糙。许多的研究材料散落一地，有些甚至被疏於照料的蜡烛的蜡油给黏封起来。傀儡、鬼魂、恶魔在厅堂间无人管理地乱走。我不得不说，我期待更高级的死灵法师研习!"
D.Strings[117629]="今天有一群强盗闯入学院，四处杀戮并进入了墓穴。当他们打断了在前厅的研习，附近的学生还继续他的练习，愚蠢!厅堂中的部队足以打败一只军队，但他们却屈从於一群废物。傻瓜!"
D.Strings[117630]="我那时候正在上加丁院长的课，入侵者突破了观察室的大门，直闯墓穴!加丁那个疯狂的混帐躲在书柜後面，咯咯笑着看他们杀死墓穴中的每个学院人员!然後他突然跳上前，大喊着「正在上课!」他神经错乱了吗?我打算要转学到斯坦索姆!"
D.Strings[117631]="今天我成了斯坦索姆内的图萨丁死灵法师!我很疑惑为什麽没人去把那些火给扑灭，而且我窘困万分地发现通灵塔居然和屠宰场的大门连结?这是什麽鬼系统!如果我们希望阻止别人进入屠宰场，为什麽不乾脆把大门锁上?然後把钥匙给丢了?"
D.Strings[117632]="我开始学习为什麽这个地方如此落後。那个自负的浑球整天骑着一匹腐烂的蠢马四处闲逛，然後自称是斯坦索姆的瑞文戴尔『男爵』。这个家伙一定是误以为天谴军是什麽可爱动物区之类的，他每天下午都要花一半以上的时间，把信徒、爪牙和傀儡召集成一小群，然後把他们驻紮在城市各处!"
D.Strings[117633]="等到男爵完成了一天的下午茶游行之後，一群，呃，就叫他们支持者吧，横冲直撞地闯入城市，把男爵的布置全数破坏。我跟他说「把大门锁上。」「我在通灵塔中的部下会保护斯坦索姆，小鬼!」他向我保证。我开始打包，并且预定了从後门离开的位子!"
D.Strings[117634]="看来我做了聪明的决定。根据从城市里升起的烟雾，我的班机还蛮准时的。在斯坦索姆工作真是场无利可图的冒险，除了我偷那个浑球的玺戒。那个蠢货只会带着精致的赝品看着我开心地躲在纳克萨玛斯的高墙之後。"
D.Strings[117635]="我今天来到了伟大天谴军团的战争工厂!纳克萨玛斯蓄势待发。我突然发觉他们使用更愚蠢而令人困惑的机械装置来强化至为关键的传送系统，除此之外，这艘船看来还不错。我的思绪转向更有利的研究，直到我被那些邪恶的奈幽虫族诱入邪道……"
D.Strings[117636]="奈幽虫族的提议多不胜数。总是用那种令人毛骨悚然又嗡嗡单调的声音呼唤我。邀请我去研究他的『起居室』。我打算把我自己隔离在古鲁斯房间後面断掉的排水管那边，那是唯一一个那些虫子不会跟着我的地方。我快要精神衰弱了!"
D.Strings[117637]="我不知道这群懒散的笨骨头和腐烂的屍体要怎麽征服整个艾泽拉斯?他们那种自我挫败的虚伪家伙缺乏任何可见的自我防卫能力!而我怎麽也无法阻止那些讨厌烦人的虫族一直在跟踪我，污染我的美梦!"
D.Strings[117638]="虽然这对我近期受雇於天谴军团的冒险中算是个转折，一群冒险者闯入了亡域，杀死我不少的同僚。唉唉，连在费琳娜教徒中的红发辣妹都被杀了，那个恶心令人害怕的大蜘蛛甚至不让我跟她讲话!我讨厌这个地方，等我变成不死生物，我『一定』要离开这里。该是战斗的时候了!"
D.Strings[117639]="在服务於天谴军时的接连失败，我发觉自己的标准甚至高於组织中的较高层级。由於社交权力结构的缺乏弹性，於是很难平衡任何试图对现存社交挑战做出的变化。"
D.Strings[117640]="幸好，这个组织提供低技术的工作机会给那些愤恨不平的人，或是因为某些疾病而不便的人(以我的例子就是死亡)。"
D.Strings[117641]="我开始相信一件事。死亡的到来是冰冷而无法实现的，也不会给予任何答案。我从俗世的制约中挣脱，但我感受不到解脱，因为感觉不到我的心。我就是感觉不到。我只希望再次死去，在贵族的炽热愤怒和慈悲胸怀之前，在光荣的战斗之中!"
D.Strings[117642]="亡域被召回了寒冰皇冠。我们负责补给与人员运输，这城市又再次充满了活力!我却不同。我感觉到完整。我感觉活了过来。我感觉到祂的完美会指引我。我明确地知道我自己的位置，当士兵到来时，我会考验他们。"
D.Strings[117643]="脑脑脑。脑~~~~~~我要脑!!!!!!!!!!$B$B<如此重复了四十多页。>"
D.Strings[117644]="这是我的符文刃:虽然这很多类似的，但这是我的$B布洛莫斯女士着$B$B欢迎，死亡骑士。现在，讲师拉祖维斯应该开始教导你们何谓死亡骑士的第一课。让我来告诉你们什麽才是死亡骑士最需要守护的珍宝，你的符文刃。"
D.Strings[117645]="如果没有你的手去导引，你的符文刃只是空壳。分开时，你们只是破碎的存在;虚弱无力。当你发现你手上没有符文刃时，你唯一的任务就是尽快找到下一把。"
D.Strings[117646]="身为死亡骑士，你应用符文刃压制那些胆敢反抗巫妖王的人。像你这样的人，年轻的死亡骑士应当成为巫妖王意志的延伸，你赋予着荣耀的符文刃，将成为你降下权威的工具。你得理解权威的规则。"
D.Strings[117647]="1.)团结一致，你的符文刃就是你身体的延伸。而你的身体属於巫妖王。$B$B2.) 当你和你的符文刃在肉体上融为一体时，你的意志，就是巫妖王的意志。$B$B3.)合而为一，你的符文刃成为死亡行经的血管，直达你的灵魂。而你的灵魂，传达的是巫妖王的意志。"
D.Strings[117648]="在你的训练课程中，你可能会发现自己被强迫专注在属於我们族类的几科学门。在这件事上我只能说;学习是值得的，不想学只是出自你们愚蠢的自尊罢了。我曾经看过这种人，他们在战场上也更加无用。"
D.Strings[117649]="很快的有些人就会发觉你的符文刃特别适合引导你们自身的愤怒。不过，这是不够的。别满足於相信你自己的符文刃只是用来专注冥想。不，远超过此。最强大的死亡骑士如同驱动意识般的使用符文刃。他们一起战斗，一心，一体，击倒那些胆敢挡路的敌人。"
D.Strings[117650]="其他人可能会发现，当符文刃充满了寒冰的能量时，刀刃也就越热情地回应他们的指令。在这个情况下，即使最锐利的符文刃也将发现更深的潜在力量。在寒冰皇冠堡垒内所充斥的能量也皆能为你所用，死亡骑士。一旦你选了这条道路，尤其是当他们被冰霜所缓慢时，你的敌人将无所遁形。"
D.Strings[117651]="也许还有一些人，在散播瘟疫与疾病给我们的敌人时，找到了真正的道路。这当然是我族特有，也值得去追求。也许有些真正强力的防御起初能抵挡你的攻击，不过每种防御都有被掩盖的弱点。只是看要怎麽挖掘出来罢了。千万别忘记，死亡骑士，导致罗德隆毁灭的不是一只军队，而是一场瘟疫。"
D.Strings[117652]="天谴军之令$B第一章$B科尔苏加德着$B$B天谴军团扎根於众千种族的愚昧之上。吾辈的崛起是罪恶与企求吾辈之死的人等所制造的产品。这些所谓的英雄在我们的面前败亡，肇因於他们为了求得愿景中的胜利而诉诸我们理想的手段。胜利让他们体认到，如果不以此等悲凉之手段，我们早已击败他们。然，在这两种情况之下，胜利或是失败，天谴军终将获胜。当他们体认到这点时，自然将归服於我们的意志之下。"
D.Strings[117653]="主上，我们的巫妖王，就是在这样的教义下诞生。$B$B腐败等同於获胜。腐败就是取走生灵中的公义和希望，以尔等力量反转之。生灵於其之弱点便有相同处:希望即为教条、公义即为狂热、生活就是体谅。了解其为何而生，逆转之。"
D.Strings[117654]="知晓腐败的康庄大道便为智慧之巅峰。心之微恙，肉体之肢解、疾病便对多数生灵有效。然，征服多数并不是我主之令，征服众人才是。愚昧的将过度资源浪费在单纯的农民上是不智的，普通的瘟疫即可征服彼等。然，拿寻常的疫病攻击经验老道的冒险者也同样不智。严谨研习敌人弱处，方能有效地打击对手。"
D.Strings[117655]="天谴军之令$B第二章$B$B生灵对於吾等最大的误解便是认为天谴军团邪恶。不过，为了使其堕落，我们让此等谬误存续，甚至散布於军团之中。天谴军的本质其实是我们超卓於凡物的枷锁之上，繁荣成长。"
D.Strings[117656]="举例来说:情感与荣耀又有什麽益处?他们确认了生灵的存在，让他们感觉『良好』。现在，他们有什麽缺点?情绪直指理性与逻辑的阻碍。荣誉，大多数时候，促使其坚持将资源浪费在必败的战役上。生灵对於吾等热衷於扮演其敌人毫无感觉，吾等塑造了他们最深的缺陷，使其成为非理性行动的化身。"
D.Strings[117657]="道德上的模糊难以净化。厌恶无法被治疗、满足。贪婪无法被驱除。愤怒无法被疗癒。因此吾等成为诸般此等情绪之化身。"
D.Strings[117658]="天谴军之令$B第三章$B$B天谴军的潜力无涯。然而，吾等不是不败之身。时时注意尔等的极限与可运用的资源。时时保持撤退计画。牺牲狂热的下等怪物是天谴军的哲学。除为了我主之外，所有形式的勇战、献身、爱族都是鲁莽而将受到严厉惩处。"
D.Strings[117659]="另一个他族对於吾等的错误认知就是我们的力量来自於生前的残余，吾等为进化之後的寄生虫，要是无法维持生命的再生便会枯萎。再一次地，这种对吾等有利的说法无须斥驳，然而，此等言论与事实相悖。吾等持续进化着，适应环境，摆脱其对於生灵的诸般枷锁。吾等无畏於争执的苦难，人口膨胀，独立，自私，短视，甚至是消亡的必然。我们听从於我主的意志，而我主将带领吾等满足慾望。"
D.Strings[117660]="吾等将其他文化的建筑、科技、肉体的精练技巧化为己用，此话为真。如同我们所作的诸多『恶事』一般，天谴军寻求的为实用主义。天谴军对於建立自身的文化并无兴趣，也无时间。由於无此等影响，天谴军所创之物，只需实用。文化导致独立，导致异议。创造力为文化之缺陷，而对於像是建筑、装备此等简易需求有着不良影响。尔等的职责不是质问、关心资源从何而来，而是如何使其效用最大化。"
D.Strings[117661]="天谴军为大地之意志。诸等众生将在吾等面前跪求唯一之解:他们冀望吾等，他们渴求吾等之救赎。吾等之习性将不受任何抵抗，吾等之命令将不被抵抗。吾等为生命自然之必然性:死亡。死亡为诸般万象之终结。不死生自於死亡。生灵如能越快知晓这无可改变之事实，便能减轻其转换之痛苦。"
D.Strings[117662]="奴仆们听令!巫妖王将让德拉库鲁指挥在祖尔德拉克的天谴军部队。我们的命令是杀掉所有东西。$B$B所有东西都得死!$B$B我们将走在亡者原野的屍体上。为了天谴军，将他们送到在赛拉玛斯的纳法勒斯王子部队!在德拉库鲁的管理下，所有东西都不会浪费!很快，我们就会喝着先知的血，变得比以往都要强大!祖尔德拉克跟刚德拉克都将死於天谴军手上!"
D.Strings[117663]="许久以前，当只有北风精灵统治群山时，一个强大坦卡族酋长的兄弟试图将这些土地据为己有。"
D.Strings[117664]="酋长的兄弟风暴之蹄，聚集了一切的力量想要征服风暴群山，打倒正统的支配者，北风精灵。"
D.Strings[117665]="风暴之蹄在北风精灵的领域中心突袭他，他差点就要成功。但是北风精灵撑过风暴之蹄的诡计，并且处决了他，作为入侵的惩罚。"
D.Strings[117666]="<这本书的大部分都已经散失或是无法辨认。只剩下一些较早的项目和一个名字「达瑞亚斯·欧莱恩」可供辨识。>"
D.Strings[117667]="第二十年，十二月二号$B$B今年的寒冷特别刺骨。不管我在长袍下穿了多少件衣物，寒霜总是能穿透并直抵骨头的最深处。大师们说凛冬将会过去，不过我常常怀疑。"
D.Strings[117668]="今天早上，一小群来自安多哈尔外围农场的工人被带到紫罗兰城塞的医护室。我并不清楚什麽困扰着他们，不过我偷听到其中一个在抱怨身体虚弱、恶心想吐。希望大师们能选我为助手来帮助他们治疗这些人。"
D.Strings[117669]="两小时之後$B$B多麽幸运!其中一位大师告诉我，我将帮助那些从安多哈尔来的农夫。我要好好利用这个机会来展现所学。"
D.Strings[117670]="六小时之後$B$B事情的发展与我的预期有极大的出入。甫抵此地，农夫的病情就开始急遽恶化。其中一位的皮肤几乎长满了令人发痒的脓疮。我对病情最严重的一位用上了城塞内效力最强的药草和膏药。在接下来的几小时内应该会有显着的改善。"
D.Strings[117671]="十小时之後$B$B情势快速地失控。所有治疗对象的身体都有损伤并不断渗漏出黄绿色的液体。他们绝大多数都已经昏迷。少数尚神智清晰的反覆的抱怨关节轮替性的麻木与痛楚。病患的眼睛逐渐地变成乳白色。"
D.Strings[117672]="所有尝试减缓疾病蔓延的努力都宣告失败。在学徒中谣传这疾病也许是因为魔法所造成;大师们很快地粉碎了这些谣言。许多与我共事的学徒，出自於对疾病可能会传染，甚至突破我们个人护咒的恐惧，都找藉口离开了。"
D.Strings[117673]="我到阳台走走，试着厘清思绪。不过短短数分锺我就跑回室内。我的手脚因寒冷而麻木，而我的耳鼻有轻微冻伤的迹象。下次我必须更小心谨慎。"
D.Strings[117674]="十三小时之後$B$B愿圣光给予我们救赎。$B$B所有病患从眼睛跟耳朵开始严重的出血。大师们相信他们活不过一个小时。一切阻止疾病恶化的努力都失败了。我已经试着尽力减轻他们的痛苦。我只期盼能在他们死亡後学到我们该知道的。没有活人应该承受他们所承受的苦痛。我要陪他们到最後一刻。"
D.Strings[117675]="让整件事更糟的是，守卫在花园里发现了一个一年级学徒的屍体。未经证实的谣言指出他是被冻死的。达拉然数十年内不曾这麽冷过-甚至从来不曾。"
D.Strings[117676]="十八小时之後$B$B 来自安多哈尔的农夫们死了。我一度以为他们已经安息了，但我错了。在最後一个咽下最後一口气数分钟後，恐怖的事情发生了。他们布满疾病的屍体动了起来并开始抓击我和其他在医护室的法师们。在短暂的困惑之後，一位大师组织了反击来击退这些活屍。这些不死生物很快的就被我们所集结的秘法之力击败。"
D.Strings[117677]="伤亡十分有限。几个学徒被抓伤;其中一位被咬伤需要缝合。没过多久守卫们便来护送我和其他数位学徒回房间。我试着探听发生了什麽事，不过他们不肯告诉我。当我们被带到通往房间的走廊时，数组武器出鞘的守卫经过我们。这就是战争的气息吗?"
D.Strings[117678]="在被带到我的房间之後，我被告知将房门上锁并且不准出门，直至任何一位大师亲口告诉我已经安全了。到底怎麽了？世界大乱了吗？"
D.Strings[117679]="二十四小时之後$B$B我已经二十四小时没睡了。我精疲力竭，但我的房间太冷不能入睡。我试着与其他被困在房间的学徒们沟通。透过他们我理解到整个城塞进入了警戒状态。大师们组织搜索队试着找出在背後操纵那些屍体的死灵法师。"
D.Strings[117680]="从科尔苏加德之後在达拉然再也没有实务的死灵法师了。希望在今天这事件背後运作的恶人能很快地受到制裁。"
D.Strings[117681]="三十八小时之後$B$B隔离解除，我们这些学徒终於能离开房间。死灵法师并没有被抓到，不过大师们相信他并不在城塞内或在达拉然附近。"
D.Strings[117682]="我们重回工作岗位研究这些疾病。鉴於屍体大多已经毁损，进程十分缓慢。大师们邀请了珍娜·普劳德摩尔女士来帮助我们研究。我听说她十分漂亮；我期望与普劳德摩尔女士一同工作，能让我忽略这该死的酷寒。"
D.Strings[117683]="<该日志严重破损以致无法阅读。>"
D.Strings[117684]="问法师!$B$BQ: 我的朋友们告诉我研习魔法并成为一个法师会让我变的身体虚弱，而且不受女士欢迎。这是真的吗?$B-吉米 「不安的」 陶森德"
D.Strings[117685]="A:别担心，吉米。你的朋友提及的是一个不公正的刻板印象-通常来自少数懒惰法师和他们不正常的饮食习惯。要在维持高峰体能状态的同时掌握操纵宇宙组成的技巧是完全可行的。即使是祈伦托的成员，在他们忙碌的行程下仍能透过严格的饮食控制与健身将身体状况保持的非常好。$B此外，有哪个女人不爱变形术?"
D.Strings[117686]="Q:我的父母并不支持我想成为法师的决定。他们认为秘法是危险的，而且是通往其他更加「凶险」的魔法，如恶魔学的捷径。我不想出卖自己的灵魂。他们是对的吗?$B-约瑟夫·寒冬$B$BA:您父母的恐惧是没有根据的。并没有明确的证据支持那些法师转往恶魔崇拜或是死灵法术的故事。跟你的家人保证一切都没有问题。"
D.Strings[117687]="Q:我最近刚开始研习秘法，到目前为止我的朋友只会嘲笑我。他们似乎只有在制造食物、饮料和将他们传送到世界各地的时候才会需要我。何时人们才会开始尊重我?$B-葛列格里 「多尔玛」 亚当斯$B$BA:当你学会炎爆术的时候。"
D.Strings[117688]="有些人指责法师们是个不问世事、自我中心的团体。我们必须让你知道这是十分偏离事实的。法师是一群有爱心的人们，并且为了你的福祉锲而不舍地追求知识与力量!什麽，法师该如何替你服务?很高兴你问了!"
D.Strings[117689]="对在大众面前演讲紧张吗?想像你的听众只穿着内衣没有用?那把他们当成一群绵羊如何?还是没用?我们会直接把你的听众变成绵羊。$B$B告诉你的法师朋友在你身上施展缓速护符并花时间好好地闻闻玫瑰花香。在赛跑时施展也很有趣!$B$B传送是最时髦的移动方式。没有什麽比虚空龙香味更能搞砸你得到第二次约会的机会。"
D.Strings[117690]="一个法师的朋友永远不会挨饿口渴。召唤出来的食物没有脂肪!$B$B 认为一个冰酒杯最能让你的麦芽酒冰冷爽口?你应该试试寒冰箭酒杯。$B$B研究指出许多文学杰作被创作出来时作者都有受到秘法智力的加持。"
D.Strings[117691]="请法师替你施展暴风雪好让你每年都能享受一个白色冬幕节。（警告:站在秘法暴风雪底下可能导致轻微的手指刺麻感与充满痛苦的死亡。）$B$B谨记:当任何东西出错时，法师就在一个闪现距离之内。$B$B 这本小册子用召唤出来的纸张所印成。"
D.Strings[117692]="以前曾经有位法师-他不会施展火球术，变形术，或寒冰箭。当他造水时，他只造出了烂泥巴。他的秘法智力只会令目标更笨。毫无争议的，他的老师们一致同意邦哥朵夫是达拉然最差的法师。"
D.Strings[117693]="条目一$B$B在我还没搞清楚状况之前，毁灭就降临在我们身上。大地震动，而自从第二次大战以来便是达拉然要塞中心的金色尖塔也开始崩毁。$B$B我记得当我看到父亲的脸被倒塌的鹰架埋没时，我开始大叫，但我什麽也听不见。即使在恐惧中，我想起我所受过的魔法训练。即便能稍微让灾难减缓一些也好-但法术完全失效。恶魔的力量阻止了我所有的努力。在绝望中，我闭着眼睛等待。但不管怎样，我还活着。"
D.Strings[117694]="条目二$B$B在过去的数个小时，废墟不停地变化。每当我以为这一切已经过去，总会有沉雷般的巨响与震动传来。我蜷伏在一个曾经能囊括繁华市集景色的拱道之下。有多少次，我看着我妹妹背满商品从拱道下走回来?如今，仅余尘土乱石。"
D.Strings[117695]="条目四$B$B我必须相信祈伦托。这些达拉然的大法师不会放弃他们的子民。这个困住我的废墟对一个老练的法师来说不过是件小事。他们终会找到我，而我终会完成我的训练并成为他们的一员。"
D.Strings[117696]="条目五$B我试着呼叫，但这里完全没有我的家人或其他人存活的迹象。在上方，万物皆寂。我不敢肯定我活了下来是好运还是厄运。我的心脏终会追寻其他人的脚步归於平静，但我的思绪充满恐惧。"
D.Strings[117697]="条目六$B$B随着周围越来越暗，空气也变得稀薄。我召换来书写的微弱光线已经烙印在我眼中。我无法再继续写下去。我的精力必须留给尚未来到的救援。我斗胆地希望这些纸张能永存，假使我办不到。我将成为一籁天听，高歌着穿越这深渊，直至消逝成喃喃低语，最终逸散於穹苍。"
D.Strings[117698]="<由大法师安斯雷姆·织符者技艺高超的手所写下>"
D.Strings[117699]="魔法神奇的天赋，能被用来达成许多目的。我们这些研究者发现将魔法这个怪异的技能分成八大范畴能更加深入的理解魔法的本质。这些范畴通称为魔法，「系别」，他们经常被分开学习，而法师们通常会专精於一种系别。有些法师试着精通所有种类的魔法，但甚少有人能完成这个崇高的目标。在这本秘典中，我们会试着个别探讨所有系别的魔法，与专精於这些派别的法师。"
D.Strings[117700]="\"所有魔法的系别，都能利用不同的能量来源，合并施展出强大的法术。一些这类强大法术，会在接下来的系列书中被探讨，不过要特别注意的是，合并不同种类的魔法可能极度地危险－特别是对初学者。$B$B在这你会学到所有魔法系别的基础。谨记在心:请勿滥用魔法，并且不要在没有适当监督时练习魔法。\""
D.Strings[117701]="防护系主要是关於保护性魔法的研究，同时也是对年轻法师来说最重要的系别之一。最普通的防护法术是法力护盾，一个以纯粹法力作为屏障来保护施法者免受攻击的法术。透过适当的施展，法力护盾甚至能抵挡最强大的攻击-但法力护盾对见习生来说相当困难。一个法师通常要花上数个月的练习来施展最基本的法力护盾。因此，更加基本简易的替代品出现了。"
D.Strings[117702]="一系列的「元素护盾」法术被发明出来帮助法师，免於旅行中可能受到的攻击。这些法术需要的能量远少於法力护盾，同时也更容易维持，但是效力不及法力护盾。例如霜甲术，仅仅只会降低攻击的效率，而不能完全抵挡。其他更精深的护盾法术则有较多的优点-例如，魔甲术能帮助法师回复魔法能量。"
D.Strings[117703]="秘法技艺的练习者通常充满野心，所以我们常常陷入魔法轻微失控的窘况。「结界」法术因此而生。结界法术是快速且强大的咒法，用来保护法师免於特定种类的元素伤害-特别容易发生於施法者在练习其他派别的法术时。因此防护系法术是不可或缺的。"
D.Strings[117704]="王子凯尔萨斯·逐日者，是最着名的防护系法师。虽然王子在各派别的造诣都十分高深，凯尔萨斯创造了一系列在达拉然中，无人能与之比拟的法力护盾。值得一提的尚有秘法师杜安，他结合了塑能与防护，使他能在花时间施展一个强大的范围法术的同时保护他自己。这个「自爆」法术，提供了几近无敌的宝贵数秒，但仅有少数法师有此才能，可以安全地施展这个法术。"
D.Strings[117705]="召唤系则以召唤为主-包括生物和非生物。可曾在荒漠中渴望一杯清新甘醇的泉水?我的朋友,召唤系正是解答。随便问问我们任何一人，没什麽比创造一片新切面包或一杯水更让人开心了!"
D.Strings[117706]="更加专精的召唤法师能同时召唤出数杯水，甚至装满一个大啤酒杯。有些勇敢的法师在召唤水时忘记了玻璃杯－召唤水元素由此而来。水元素是巫师最好的朋友。(绝不是恶魔犬-事实上恶魔犬一点也不友善。)一个被召唤出来的水元素是战斗中强大的盟友，一个忠实的听众，甚至嚐起来味道还很棒!"
D.Strings[117707]="有些巫师选择走上令人振奋的召唤之路。巴琳达·石炉上尉是一个标准的召唤系战斗法师。在我辈之中，最有名的召唤师也许就是大法师聂拉斯·埃兰了。埃兰不但能同时召唤数种元素，他同时还专精於召唤闪闪发光的频果汁。特别注意埃兰不是个小丑，魔法本来就是关於这些东西。"
D.Strings[117708]="预知系是关於资讯收集的魔法。强大的预知法术能让法师视物於千里之外，甚至看到隐形之物。最普遍的预知法术是占卜，主要用来观看远方的事物-甚至能看到其他界域。"
D.Strings[117709]="藉这个机会我必须提醒我的学徒，占卜池绝不是玩具。特别是绝不应该用来收费提供偷看异性的服务。这是我最後一次警告。"
D.Strings[117710]="传说般的法师麦迪文，也许是有史以来最强大的预知系大师。他的法术让他能够从我们的世界偷看德拉诺-甚至更远的地方。我们对麦迪文曾经拥有的真正力量只能臆测。"
D.Strings[117711]="附魔是一个将魔法能量附加到物品或人身上的过程。有些附魔是暂时性的，有些则是永久的。学习附魔十分困难，但也许是获利最可观的魔法。我十分乐於研究附魔，因为这个系别比较不会把自己炸了。"
D.Strings[117712]="分解则是用来将魔法能量移除或驱散。驱散魔法或许是一个法师最重要的武器，因为驱散魔法能将抵销一发误射法术的毁灭性结果。将一个魔法物品永久的分解也是可行的。这个过程会产生一种独特的法力水晶，能用来附魔在其他物品之上。虽然可能价格不斐，但通常这是一个年轻法师学习附魔最好的方式。"
D.Strings[117713]="前面提到凯尔萨斯·逐日者王子在防护系魔法的造诣，王子在附魔方面同时也是第一流的。他不只能创造强大的魔法武器，他甚至能遥控这些武器来替他战斗。如此即使落单也能让他宛若被一群技艺高超的战士所保护。的确是个强大的防御。"
D.Strings[117714]="无敌的$B$B阿萨斯·米奈希尔王子受人敬爱的战马$B$B一生忠诚且有一颗崇高的心，愿你安息。$B$B纯洁溪水和油绿草地，一个忠实的朋友。"
D.Strings[117715]="幻术系是一门欺骗真实的学问。幻术迷雾能让一个法师无法被看见或听见，或将一个地点的影像扭曲成另一个完全不同的东西。幻术能被用来作为伪装或控制，不过请特别注意，预知系存在用来对抗幻术系的魔法。将幻术系用来作为魔法事业生涯的根基是不可行的。"
D.Strings[117716]="与大众认知相反，幻术远远超出局限於客厅或起居室的玩意。隐形术是一个战斗法师最重要的技能之一，因为你经常会陷在危机之中，而需要一个快速方案以紧急撤退。幻术也能用来欺骗你的对手，让他以为你在别处，甚至让你的敌人自相残杀。这并不容易，但一个幻术师能将盟友变成敌人－而将他的敌人变成盟友。"
D.Strings[117717]="「前大法师詹迪斯·巴罗夫-愿她的灵魂安息-是一个典型的天才幻术师。在她生前她发展出一个法师能让她复制出数个几乎无法分辨真伪的幻影。这些幻影能在许多不同的地点复制她的动作，使她的敌人几乎不可能找到她。这个法术「几乎」是绝对可靠的。但也让我上了一课-只做到「几乎」还不够。」"
D.Strings[117718]="死灵系是关於死者的研究。这系是被禁止的，而且应该全力避免。我在这里讨论死灵系，是因为这是我们的义务与责任，去了解我们敌人使用的魔法-而且请不要被混淆，所有施展死灵系法术的法师都是你的敌人。死灵法师和他们的手下是所有生灵的大敌，我们应该全力去避免他们所产生的任何影响。"
D.Strings[117719]="死灵魔法除了单纯复苏死者之外还有许多功能。这种腐败魔法的大师能召唤脓疮疫疾，编织暗影成为燃烧性的能量，还能运用死亡的力量毁灭生命。死灵系也能被用来重建不死生物的血肉，使这些邪恶怪物能在被毁灭後再次复活。"
D.Strings[117720]="前大法师科尔苏加德也许是近代死灵法师最值得一提的人。他的事迹包括了天谴军初期的快速扩张与罗德隆的沦陷。现在，科尔苏加德以巫妖的身分统治着飞行堡垒，克萨玛斯。他的存在对我们来说，是个迫在眉睫的威胁。"
D.Strings[117721]="第九个也是最後一个系别是转化系。这是所有系别最受欢迎也是最实用的之一，让法师能操纵时间与空间。最具代表性的转化系法术也许就是变形术了。变形术让法师能将一个东西-或一个人-变成其他事物。很幸运地，对我大部分的学生来说，效果不是永久的。我见过不止一个粗心学徒变成羊，猪，或更糟的东西-别问我那是什麽。"
D.Strings[117722]="第二知名的转化系法术是传送术。最基础的传送术是闪现，同时也是最实用的。闪现能用来快速摆脱敌人，或拯救一个不小心掉下悬崖的法师。除非必要，不要尝试用闪现来避免摔死。这是一个你一生只能失败一次的把戏。"
D.Strings[117723]="在传送前，请百分之百确定你的目的地。我们发明用来传送至特定地点的法术不是没有原因的-在飞行中施展传送术通常会导致一个死透了的法师-卡在墙里，椅子里，或另一个法师里。我不是在开玩笑。"
D.Strings[117724]="操纵时间的法术也落在这个范畴内。在掉落时，广受欢迎的缓落术是个比起摔死来说更佳的替代方案(而且比闪现更可靠)。更高超的秘法施法者能习得减缓对手速度的法术。我还有听过能加快移动速度的法术，但我从未亲眼见过。"
D.Strings[117725]="珍娜·普劳德摩尔女士是位技巧高超的转化系施法者。她发展出群体传送术更加强大的变种，能够将快速移动她大部分的军队。这法术让她在战场上神鬼莫测。"
D.Strings[117726]="艾路斯崔·绿叶 着$B$B立刻停止!想清楚你在做什麽。秘法真的适合你吗?"
D.Strings[117727]="事实如下:$B-魔法是一股危险的力量，每年都造成数百万人死亡。$B-秘法具高度成瘾性，当你一旦开始练习就再也无法停止了。$B-学习简单的秘法法术，一开始可能看起来相当无害，但通常是通往更加艰深危险法术的捷径。你最终甚至可能对恶魔魔法上瘾。$B-在分娩时施法会对你的孩子产生重大健康危害。$B- 滥用魔法可能导致暴力与死灵法术。$B- 秘法一点都不酷。"
D.Strings[117728]="这就是为何我们要创设抵抗魔法滥用教育学程(M.A.R.E)计画来教导人们滥用魔法的危险。我们的任务是向世界展示我们完全能不依靠魔法生存。你能从别的地方找到乐趣，例如种花或是编竹篮。听起来很刺激吧?"
D.Strings[117729]="此外，我们的计画还帮助魔法成瘾者解瘾并且重新融入社会。创立仅仅六天，我们的计画就和伊露恩的女祭司与塞纳里奥议会建立稳固的关系。这些组织有能力并且乐意帮助您快速复原。记住，学习如何爱护自己永不嫌迟!"
D.Strings[117730]="目前艾泽拉斯充斥着许多独特的挑战，让人很难保持一个安全无魔法的生活方式。我们能帮助您找到那条安全舒适的捷径。已经有数十人从我们充满魔法替代方案的生活方式受益。也许您就是下一位?"
D.Strings[117731]="觉得不太高兴?需要一些能量?那很多能量如何?热呼呼燃烧的能量如何?$B$B试试皮洛可全新的熔岩冲击。你会爱上它的甜蜜新鲜滋味和巨大纯粹的能量。需要快速恢复精神?没问题!即使在最疲倦时熔岩冲击也能帮你快速充电。"
D.Strings[117732]="受重伤了吗?我们能支援你!熔岩冲击能给你额外的能量让你逃出生天!*$B喜欢火吗?曾想像过若能喝下液态火该有多棒?如果是，你将会爱上皮洛可全新的熔岩冲击!嚐嚐燃烧吧的滋味吧!$B$B*最近的研究显示熔岩冲击不能以任何形式治疗伤口。熔岩冲击有可能让你从随机位置大量出血。"
D.Strings[117733]="警告:熔岩冲击并不适合所有人。孕妇，儿童，或有可能怀孕的妇女在服用熔岩冲击必须先谘询医生。"
D.Strings[117734]="「可能产生的副作用包括:口乾舌燥，肚子痛，乾眼症，消化不良，背痛，骨骼与关节疼痛，轻微外皮损伤，内出血，暂时性疯狂，熔岩冲击上瘾症，魔法上瘾症，纵火狂症，对蜘蛛恐惧症，闪电眼，心悸，发烧，流产，失眠，对冷铁虚弱症，歇斯底里，脑袋中出现随机歌曲，哮喘，恶魔附身，头痛，脚痛，无法正确的使用字母「R」，和死亡。」"
D.Strings[117735]="注意:连续喝下多瓶熔岩冲击可能会导致自燃。$B$B$B立刻试试最新的熔岩冲击!"
D.Strings[117736]="当安东尼达斯在祈伦托成为一名学徒时，他不过是个男孩。他是个不屈不挠的学生，在达拉然的魔法图书馆里大量吸收知识。仅仅数年，安东尼达斯就远远超越了他的同侪并赢得他们的钦佩和长辈的尊重。"
D.Strings[117737]="由於兽人收容所的超载，与因应其费用而提高的税率，联盟显的岌岌可危。而缺乏共同的敌人，更使得第一次战前的政治对立与零碎口角重新浮上台面。"
D.Strings[117738]="此外，在北方开始流行瘟疫。在经过调查後，安东尼达斯发现柯尔苏加德这位祈伦托的成员曾施展过死灵法术，并推论出北方的瘟疫是魔法所造成的。以大法师为首，达拉然的领导们建议隔离疫区。"
D.Strings[117739]="出於害怕隔离疫区可能产生的强烈抗议，泰瑞纳斯国王并没有接受他们的请求。就在此刻，先知造访了白发苍苍的大法师。他警告了瘟疫的可怕，并告诉安东尼达斯他认为艾泽拉斯已经没有希望了。先知建议安东尼达斯带领他的手下前往西边的卡林多大陆，如此方能拯救他们的性命。"
D.Strings[117740]="但是安东尼达斯已经超过七十岁。他很有智慧，但也十分固执和提心吊胆。虽然他的学徒，珍娜·普劳德摩尔女士，发觉了先知的强大力量并建议他留心先知的指示，安东尼达斯仍将先知当成了个疯子并把他赶走。"
D.Strings[117741]="大法师决定留在城市中继续调查北方的瘟疫。关於他对瘟疫的研究可以参阅:《大法师安东尼达斯的日志》。最终，他派出珍娜去调查。她与阿萨斯·米奈希尔王子同行。"
D.Strings[117742]="当安东尼达斯寻求阻止瘟疫的方法时，阿萨斯陷入了疯狂，毁灭了斯坦索姆，并前往北裂境追猎惊惧领主玛尔加尼斯。在年老的大法师找到解药前，阿萨斯与巫妖科尔苏加德带领不死军队穿越提里斯法和罗德隆，并摧毁沿途的一切以增强其军力。"
D.Strings[117743]="很快地他们兵临城下，企图毁灭达拉然并取得麦迪文之书以用来召唤阿克蒙德。$B$B安东尼达斯，站在阿萨斯与他的不死军团之前，拒绝交出麦迪文之书。安东尼达斯运用他无人能比的防御魔法设立了一个能摧毁任何不死生物的魔法力场(一个现在防御力场的早期版本)。"
D.Strings[117744]="遗憾地，这样做还不够，阿萨斯找到方法来驱散结界。他直抵达拉然的中心并冷血地杀死了安东尼达斯。尔後科尔苏加德与阿萨斯一同进入了紫罗兰城塞取得了麦迪文之书，然後召唤了阿克蒙德。$B$B当不死军团前往下个目标时，阿克蒙德彻底毁灭了达拉然和他的魔法尖塔群。安东尼达斯与达拉然，现在只余一片废墟，再也不复存在。"
D.Strings[117745]="[终章]$B$B安东尼达斯，为了保卫他唯一的家园而身亡，在许多方面足为後人典范。他的成就，勇气，和记忆是旧世界和其遗产得以延续的证明。在这个兵荒马乱的世界，脆弱的新联盟不过是个对罗德隆众子中最勇敢，最伟大的英雄之一的纪念和明证。"
D.Strings[117746]="长毛兔         $B杰佩托·乐吱，玩具商$B$B<整本书充满了大张彩色图片与伴随其间的简短句子。"
D.Strings[117747]="很久很久以前有一只兔子。他的名字叫长毛兔。"
D.Strings[117748]="他镇日啃着花朵。「花好好吃!」长毛兔告诉他的朋友。"
D.Strings[117749]="他的朋友叫做长毛狼。长毛狼是一只座狼。"
D.Strings[117750]="长毛狼喜欢跟长毛兔到处晃，看长毛兔吃东西。"
D.Strings[117751]="有一天，当长毛兔在吃嫩草时，长毛狼跑到他身边，然後把他吃了。"
D.Strings[117752]="「长毛兔好好吃!」长毛狼开心地大叫。"
D.Strings[117753]="这故事告诉我们:别和座狼做朋友。"
D.Strings[117754]="十月八日。$B$B 如同我之前提过的，我对於某些派系的法术那可怕的潜在危险性，与这类法术几乎毫无管理机制的现状，感到非常厌恶及反感。更糟的是，广泛研究显示，这些不安定系别有一股趋势:在越来越容易习得并且施展的同时，法术所产生的效力也越来越强大。"
D.Strings[117755]="我的一个学生今天问我，「为何当恶魔传送门能有两倍大小和十倍时效时，我们还要在传统传送门上加诸各种限制?」这名学生还不懂理论与实际之间的抽象概念，但这问题让我思考其中矛盾之处:当魔法存在那麽多令传统魔法相形失色的变种时，练习传统魔法的未来在哪?"
D.Strings[117756]="我尽我最大的努力，去抑制恶魔魔法和死灵魔法在这的发展，但同时我也被这些法术所拥有的庞大潜能所困惑。我拒绝相信这些法术/u。但是当你亲眼目睹巨大的炼狱火，抑或辽阔的土地在举手之间枯萎，我害怕，我的信念将从我同侪心目中的真理，转变成教条。"
D.Strings[117757]="十月十六日。$B$B我把注意力转移到在北方肆虐的瘟疫。我把我大部分的课堂都取消以研究这个可怕的异变。$B我非常小心谨慎的取得了一些受感染的谷物。令我惊讶的是，我马上注意到，这个包裹显得十分无害。没有任何变色，也没有明显的味道，其他捆谷物也没有任何变异。$B我立刻清楚的知道为何瘟疫会如此迅速的散播。"
D.Strings[117758]="十月十七日。$B进一步的研究指出了令人困扰的结论，与甚至更令人困扰的意涵。$B初级测试显示瘟疫对非人生物仅有非常有限的效果。症状包括了疲倦，恶心，发烧，轻微幻觉，但甚少导致死亡。但一旦来到人体组织，瘟疫一致且以空前的速度演变成坏疽。"
D.Strings[117759]="这种致命有效率的杀人瘟疫，仅仅在人类口粮中发现，绝不可能是巧合。当然这两件事之间可能没有关连，但我依然决定派出更多资源来找寻瘟疫的发源地。我害怕在瘟疫背後有只无形之手在推动。过几天，我将在长考之後，派出代替我的人去调查。"
D.Strings[117760]="十月十八日。$B$B我忽略了一个重大关键，一个非常巧妙地隐藏起来的关键。因此我得到了两大结论:瘟疫是为了杀人而存在，而且是人为之物。$B瘟疫长时间的肆虐造成了屍体复苏活动的现象。因为这个现象非常不明显，我将其认为微弱的副作用。但是，这股能量十分持久且不曾减弱。我因而灵光一闪，一道清晰的讯息浮出:屍体在等待在某人，或某物。"
D.Strings[117761]="当时我并没有任何证据，但我依然不断追寻。我用我有限的死灵法术知识对屍体下了一些诅咒。那时我并不想令死者复活，只不过是想改变或分辨屍体辐射出来的能量。想像一下，当屍体跳起来攻击我的时候，我有多麽惊吓。"
D.Strings[117762]="我马上把屍体焚化，但我现在後悔了。不过我也证明了我的理论:屍体(同理可以延伸到瘟疫)在等待更进一步的指示。很明显的因瘟疫而死的人不过是在他们坟中浅眠，等待一个能唤醒他们的死灵法师。$B$B 简而言之，毫无疑问的瘟疫是由魔法所造成的。"
D.Strings[117763]="十月二十号。$B$B 我决定派出我最信任的学徒，珍娜·普劳德摩尔去调查瘟疫起源。根据我的研究，我相信只有我最好的学徒，才能应付任务中未知的危机。她将会随身携带一份这本日志、与一些瘟疫研究资料的拷贝。当然我会公开这些资讯，警告人们小心这个即将到来的威胁。"
D.Strings[117764]="我希望我能亲自调查，但泰瑞纳斯固执的反对。我认为没有什麽比立刻隔离北方疫区更重要。无论如何，我对珍娜的机敏有绝对的信心。我怀疑除了她或我之外还有任何人能阻止瘟疫的蔓延。$B$B -安东尼达斯-$B<这里被盖上代表六人议会的缄印>"
D.Strings[117765]="我们并不想取代传统的移动方式诸如船，飞艇，或者飞行。这些是便宜实际且安全的运输方式。但透过正确的方式使用传送门，一样安全而且速度更快。但是，当传送门向大众开放时，没有例外地，屡屡造成社会的许多困扰。在所有祈伦托开发出来且维护的法术中(包括变形术)，传送门已经濒临封印，仅限於紧急用途。"
D.Strings[117766]="为何有这麽多麻烦?首先，地脉不会从树上长出来。巨大的交通流量会让地脉从根基逐渐耗损因而必须定期更换。我们从每个法师那回收材料，并鼓励这些法师将费用转嫁给使用者。不过这不过是杯水车薪，仅能负担更换管线所需的材料费，而无法负担所需要的人力以及时间。"
D.Strings[117767]="记住:一个最常使用的传送门就是最有效率的，同一个传送门使用人次的增加并不会加重地脉的负担。我们正在规划一个能给予创造五人以上传送的法师减税优惠的「传送门共乘」计画。请查看最新的《祈伦托月刊》以获取「传送门共乘」计画的最新进度。"
D.Strings[117768]="再来，也许一个正确使用的传送门就和飞艇一样安全(也许更安全，想想哥布林的工程技术)，但一个不恰当的传送门可能会产生极其严重的後果。以下是一些不能变更的传送门使用规范:"
D.Strings[117769]="规则一:不要创造一个通往祈伦托指定区域之外的传送门。传送门蕴含的庞大潜能是非常危险的。我们知道一个法师能轻易的创造通往任何地方的传送门，因此作为应对手段，我们将相关刑罚提高到最严重时可处以死刑。$B特级核发执照D-6允许自由开启传送门，但很少发出。洽询你当地的传送门训练师来获取相关细节。"
D.Strings[117770]="规则二:在正确的地方创传送门，并且正确的使用传送门。不要在某人的脚下开一个传送门。不要在传送门内外逗留。不准用传送门来丢垃圾。传送门不是护盾，不要把传送门当成雨伞或类似用途。"
D.Strings[117771]="当身体一部分进入传送门时，不要退出来。不管从里面还外面，不要试着抓传送门的边缘。传送门通常不会有手把，而干扰传送门的边界是一件危险的行为。"
D.Strings[117772]="规则三:不要强迫或设计一个人穿过传送门。这不但是一个失去潜在顾客的行为，而且还十分危险(见规则二)。"
D.Strings[117773]="规则四:不要让一个被变形的人穿越传送门。这种行为毫无例外的会产生爆炸。本条同时见於《变形术条例与规范》。"
D.Strings[117774]="规则五:不要把液体过滤器移除。这是用来避免当传送门在水下使用时可能造成的水灾。若要让一个水元素通过传送门，可以在施展时略过过滤器。但请不要在水底下这麽作!我们觉得有义务提及普通严重灾害索赔案例34-zz:〈24A.D时的湖畔镇乾旱和铁炉堡大洪水〉。"
D.Strings[117775]="规则六:标准传送门大小是三码，一尺，加三又四分之三英寸高，以及两码，八尺，九又十六分之十五英寸宽。两倍宽度的传送门需要特级核发执照G-16，通常发给拥有至少八年以上使用传送门记录良好的法师。洽询你当地的传送门训练师来获取相关细节。$B$B<这些东西写了数百页>"
D.Strings[117776]="种族口角最容易造成暴力事件和灾害，同时也占了祈伦托诉讼案件中绝大部分。变形术研究多年以来的受到持续监控和危险防治，然而在最近问题却大副增加。为了继续安全地使用这个法术，必须制定一些使用规范来遏止因?鲁莽地施展变形术而日渐增加的悲剧。"
D.Strings[117777]="短距离瞬发全身传送术必须要遵守一些特别的规定。这本书有对闪现术使用方法的重要指示，能保证你一个安全且方便的传送。"
D.Strings[117778]="规则一:不要闪现到任何人身上。闪现术，如同你所学，将目的地的水和空气代换成施术者，并且将水和空气移至原地。这个法术之所以成功和受到广泛使用，正是奠基在其简单及优雅:这法术真正的目的是将法师的身体与其前方的东西对调-随而产生的传送效果只是个附加效果。"
D.Strings[117779]="这个法术够聪明，因而在大多数时候会自动避开人体。祈伦托花了很多资源让这个法术变得更加完美，但请注意，蓄意传送至他人身上可能造成以下三种後果:施法者取代目标，目标取代施法者，或两者并存於同一空间，产生一个连天谴军团也会将之驱逐的丑恶混种。如果想避免以上悲剧，请注意你传送的目的地。因此我们订下了下一规则…"
D.Strings[117780]="规则二:看清楚你的目的地!在因人们违反规则一而产生大量的意外後，祈伦托决定将本条从规则八移到这。我们理解意外会发生，但某些意外很难完整治癒复元。法师们，当你穿越星界时，注意前後!"
D.Strings[117781]="规则三:不要闪现到你看不到的地方。这是规则二的另一种声明方式，但值得一提，因为本条最容易被刻意违逆。如同规则二，我们接到不少报告指出许多法师在闪现後的下场都十分悲惨。有些法师承认当他们被追杀时，他们故意对着一道墙，一片黑暗，或是一个箱子施展闪现术。我们无法想像这是多麽愚蠢的行为。"
D.Strings[117782]="固体之所以为固体，是因为其本身键结十分坚固。不像空气或水可以轻易的分离并且对调，固体键结将会转移到施法者身上。祈伦托觉得有义务提及，并列出所有与闪现到固体内有关的小型灾害索赔案例。记得这些案例，并且不要犯同样的错误。"
D.Strings[117783]="10012-c:「用火将酒吧的凳子从史库比·拉查特堡的屁股上移除。副作用:轻微烧伤」$B$B19798-g:「用腐蚀性烈酒将三个密银支撑棒从珍娜斯·奇力安的头上移除。感谢RAS捐赠烈酒。副作用:永久性秃头。」$B$B14761-aa:「用哥布林伐木机将辛西雅·华勒比从谷仓的墙壁移除。副作用:很不幸的十分严重，但华勒比小姐仍能用一只脚和手继续活下去。」"
D.Strings[117784]="16616-x:「用从铁炉堡运来的岩浆将哈蓝·威森从图拉扬将军的雕像中移除。副作用:中等伤害。威森先生没受伤，但附近的学童看到他从被熔化的将军中出现，从此一生都有阴影。」$B$B11773-c:「将六个多汁的西瓜从希涅拉·红刃的身体里移除。副作用:小。四个西瓜被回收并且捐赠给当地的孤儿院。」$B$B<这些东西写了数百页>"
D.Strings[117785]="如同你们所了解的，我们是一个会定时搜索当地的扭曲虚空以找回遗失物件的组织。我们找到了各式各样的财富，从零碎的魔法精华到带有秘法力量的碎片，到全套的防具和武器。最近，不幸地，我们也开始找到垃圾和废物。"
D.Strings[117786]="从广受尊敬的大法师安斯雷姆·织符者桌上发现"
D.Strings[117787]="我尽量往好的方面想，但我们可能再也看不到学徒阿果力。大法师阿塔瑞克对他的学生操之过急，结果给了我一堆只能勉强造水的笨蛋!如果我期望这些小丑能做好法师的工作，那我不如去凭吊这个连小事都办不成的男孩。"
D.Strings[117788]="奥特兰克的青草营养十分丰富，而且能替热茶添加强烈的泥土风味。我派出男孩去漂浮城市外围找新鲜的青草。当我在忙着纠正另外一个把两百年壁毯烧掉的学徒时，我忽然想到他再也没有回来。"
D.Strings[117789]="我忽然想到，当我给他这个任务时，阿果力笑的像个傻子，但我很快的把他赶走。今天早上我终於知道他的下场。我在阳台上俯瞰冰冻荒野时，我的笔记被风吹落。当我派出我的随从去拿回笔记时，她急忙的跑回来，告诉我她发现阿果力的屍体在一个冻原裂隙。"
D.Strings[117790]="当我在他的长袍发现魔狱草，我毫不怀疑男孩要替自己的死亡负责。看起来阿果力对我「去找些青草」的指示太过认真，在他出发前吃了很多魔狱草。剩下的，我相信你可以自行想像。"
D.Strings[117791]="<这个传单刚被贴上。石头上许多浆糊残渣显示这里曾被贴了许多传单。>"
D.Strings[117792]="仔细听!$B$B魔法和你的认知有极大的出入。魔法所带来的危险远超过任何好处! 问你的长者，以得知真相。趁还来得及时赶快行动! 在你把自然毁坏得无法修补前学习掌握自然，并分享万物的平衡。$B$B<一个你没见过的印章盖在传单下面。>"
D.Strings[117793]="图勒·鸦爪$B$B虽然可能的理由不一，最近在提里斯法林地和银松森林发生的事件似乎指出，图勒·鸦爪自愿地与天谴军团站在同一阵线。在洛丹米尔湖的芬里斯城堡外观也许能提供一些线索，不过现在我们的注意力必须放在其他地方。"
D.Strings[117794]="冈瑟尔·阿坎努斯$B$B推测在第三次大战中，被天谴军团杀死。$B$B冈瑟尔生前带着我最爱的烟斗。如果能找到他的屍体，我将会是最高兴的人。"
D.Strings[117795]="比索·埃斯沙德$B$B在第三次大战中被杀。比索後来成了被遗忘者的一员，必须被当成一名部落间谍。"
D.Strings[117796]="雷安娜，$B$B你不在我身边时，我每分每秒都过得十分难熬。我清醒时无时无刻都想念着你的碰触和爱抚。$B$B若星辰殒落，将没有一颗能比得上你耀眼夺目的眼睛。"
D.Strings[117797]="雷安娜，$B$B新月圆亏，我的指尖因我想到月光而颤抖着，因我想到新月那缺口彷佛流泄出墨汁般洒满整个夜空，只为遮掩我们那罪恶的欢愉。$B$B我在你身边无法呼吸。"
D.Strings[117798]="雷安娜，$B$B夜晚降临，我只能和孤独寒冷的空气作伴。瘦骨嶙峋的树枝无情的俯瞰着我们待过的那片林地，在我寻找你身影的同时不断的鞭打我，彷佛嘲笑我是个傻子。$B$B 我为你感到苦痛，惟有一个男人为了他的女人，方能感受的痛。"
D.Strings[117799]="雷安娜，$B$B当我知道邮差拒绝把我的信送件给你时，我有多麽惊讶!这是个误会，对吧?我的眼睛扫视过我所寄出的信，但我无法发现任何值得一提的笔误。如果那个蠢蛋认为我的爱人会拒绝我的回信，我将亲自把这封信送达。"
D.Strings[117800]="先生;$B$B雷安娜女士明确地要求，不论如何，任何你的讯息不得送达她那，请你不要再寄了。$B$B我的女士同时希望我简短地向你报告，因?不恰当时机的变形术所产生的事件，虽然很吸引人，却是个她不愿重复的意外。"
D.Strings[117801]="达拉然晚餐指南$B当英姬·魅光在城市重建时，开设了「英雄光临」，当地居民与游客马上有志一同地放下武器，排队享用面包大餐! 座位充足，价钱公道，酒吧提供来自世界各地的不同风味，让你觉得自己是个英雄。不管你点了什么，留点胃口给蜂蜜酒抹麋鹿肉吧!"
D.Strings[117802]="<这个破损的日志不是字迹难辨就是缺损破页。>$B$B尼可莱会怎麽想?我不敢告诉他这个声音，但我本来就没什麽机会和他说话。也许这个声音是我的潜意识?"
D.Strings[117803]="这声音坚定的不像回声，不断的告诉我还有更多即将到来。这种感觉像头痛的正面版本(如过这样说有任何意义的话)，一阵阵的温暖与点子不断袭来。举例:我知道图书馆员有一些秘密，那股声音告诉我他有恶魔文献，但是她对恶魔的理解依然少的可怜。"
D.Strings[117804]="我的潜意识再次正确。我对於他们教的简单魔法，不是用熟练就可以形容的。当我的同侪制造出饼乾时，我能召唤出丰盛的大餐。尼可莱能看到我内在的改变。他被吓到了吗?我的潜意识告诉我，他是在尊敬我。"
D.Strings[117805]="我可以去找他吗?他肯定是在北方! 我可以清楚的看见道路。救赎即将到来。还来得及。我可以让他复原，甚至更好! 运用我日渐增长的力量，我能让我们全都过的幸福快乐! 妈, 爸, 尼可莱…我们将合而为一…"
D.Strings[117806]="尼可莱害怕我;他的眼睛透露出嘴巴不敢透露的讯息。没关系，历史和我的潜意识一致同意，害怕与尊敬是一体两面。如果他离开我，我会让任何胆敢碰触他的人後悔。我的姊妹们，他们最终都会是我们的。"
D.Strings[117807]="…威胁如果我不将他的猫恢复原状，他将告发或驱逐我。一只年老的猫有什麽好恢复原状的? 我应该对他做我对猫做的事。他们竟敢在他起身对抗我时保护他，而且还是在尼可莱面前?"
D.Strings[117808]="妈竟敢骂我。她难道不了解我是谁?我能感应到他的召唤。这个城市与他的人民配不上我。厨房里的食物远多过我所需。尼可莱、妈、甚至那只该死的猫 - 他们全都将会听我的话，永远与我在一起。妈化妆台里的钱也应该是我的;只有我能帮助他。$B$B<剩下的页数一片空白。>"
D.Strings[117809]="你觉得你会施法?:新手法师问答集:"
D.Strings[117810]="波 - 一种积极热情的交配呼唤。$B 我能替你做什麽? - 这里卖酒。$B 您好 - 一种具威胁性的战吼，特别是伴随着挥手或鞠躬时。$B 你好吗? - 你妈真的是只蜥蜴吗?$B为了国王的荣耀，朋友! - 我真的很饿!"
D.Strings[117811]="- 以火攻火!一个以火构成的怪物身体并不会让你的火球术无效。试试看!结果可能出乎你意料。$B$B-为了成功而穿!研究显示，有花心力在穿着的法师，远比那些穿着破旧衣服的法师来的有效率。你最近有更换你的长袍了吗?$B$B-了解你扮演的角色! 第一眼，你的法杖可能看起来像个强大的肉搏武器，但它并不是。让那些穿着闪亮盔甲的家伙站在前线吧。也就是说…"
D.Strings[117812]="- 误击友军! 不要怕，放就对了!没击中没关系;你的秘法飞弹也不一定会打到你的朋友。$B$B - 去找个工作!一个琢磨技艺的好方法是去问别人有没有什麽需要帮助的地方。你将讶於人们多麽渴望雇用一个可靠的法师!和你想像的相反，甚至一个转达包裹的简单任务都能精进你的法师才能。$B$B - 每天种田! 你可能听过一些法师选择不用大脑的重复屠杀同样的怪物 - 通常一次数只 - 来练习他们的秘法技艺。当然这是个合法且有效率的练习方式，但长时间的重复这种练习会令你的脑袋腐朽。"
D.Strings[117813]="Q:我根本放不出任何法术。我该怎麽办?$B$BA:你可能脱水了。如果你确定你会施展那个法术，试试看喝一杯水!适当地补充水份对施法来说是非常重要的。"
D.Strings[117814]="Q:我放不出火焰冲击!我前几秒前刚成功施放，但现在一个渣也放不出来。帮帮我!$B$BA:你有施放法术的困难吗?前几秒刚成功施展吗?有些法术并不能马上重复施展。当你在等待时试试别的法术吧。"
D.Strings[117815]="Q:我偷看我了我朋友的法术书，他的法术比我多好多!我哪里做错了呢?$B$BA:首先，这是十分正常的。请记得定时去拜访你的训练师，他应该能教你一些新的咒法。如果没有，也许你要更加时常练习你已知的法术。耐心点，你会学到新法术的!"
D.Strings[117816]="Q:我的同事们造成的伤害似乎远比我多。我该怎麽赶上他们?我不想看起来像个笨蛋。$B$BA:伤害不是一切。你能用其他的方式帮助你的团队-制造些秘法点心就是个不错的方法。如果还不能解决问题，也许秘法技艺并不适合你的生涯规划。我听说当个猎人很简单!"
D.Strings[117817]="条目一) 首先，容我自我介绍。我是大法师瓦戈斯，第一只祈伦托派往德拉诺探险队的领导人。我们和一只联盟军队在穿越黑暗之门後，在法拉隆原先狞笑骷髅兽人定居处，设立了一个村庄-肯瑞瓦。多麽可爱的地方!"
D.Strings[117818]="条目四十二) 我们继续挖掘地脉，并且取得了良好的成果。我们对德拉诺和艾泽拉斯地脉相似的程度感到讶异，也许他们来自同一个起源?$B我的好友兼同事，纳伯瑞厄斯报告说，当地狞笑骷髅部落与联盟之间缔结了停火协议。我从不相信兽人，「天堂与地狱仅有一线之隔」，我告诉我自己。"
D.Strings[117819]="条目两百零五) 大部分的联盟军队已经开拔往艾泽拉斯。希望经过加密的报告，能和图拉扬将军一起安然无恙地抵达达拉然。$B耐祖奥鲁莽造出的传送门将法拉隆彻底撕裂，绿色山丘快速的崩落进扭曲虚空。我必须找到回家的路!"
D.Strings[117820]="条目一千零六十三) 十四年了，肯瑞瓦依然屹立不摇。我们每日享用一次卢瑞斯召唤的食物，而达斯立克如铁一般的法师之刃扞卫着村庄。德拉诺的毁灭似乎不全然是坏事，在这的魔法偶发事件比我们想像中的更有趣!"
D.Strings[117821]="条目一千零六十九) $B<这页非常潦草，与先前完美的字迹形成强烈的对比。>$B$B 我们被攻击了…凯尔萨斯的军队…他们有数以千计!!…飞行船…比我以前所见过的飞艇还要大上千倍…强大陌生的魔法能量…和某种法力炸弹?$B我在塔上施展了防护咒语…没有任何其他人存活的迹象…$B$B<最後一个字的字迹拖的很长>"
D.Strings[117822]="条目一千九百零七十) 凯尔军队的来袭完全出乎我们意料之外，而且把我困在肯瑞瓦的塔上。一个秘法魔像守在楼下的门口，并且被设定成具攻击性。我能读任何我想读的书，但我出不去!$B虽然凯尔的魔法让我们无法沟通，我感应到我的学徒罗樊德威还活着。"
D.Strings[117823]="老巫师的年监:联盟$B$B祈伦托一直以来都与联盟友好，使得人们可能误以为祈伦托不需要一本描述联盟种族特性的书。但我觉得事实正好相反-往往人们在反思自身後，才能真正去理解其他种族。 -老巫师"
D.Strings[117824]="人类 - 身为适应力最强的种族，人类可能成为一些最强大的法师。任何列出史上最伟大法师的一张表都会占满人类。最显着的例子也许是老巫师本身-他也是个人类。$B$B矮人 - 矮人有中等的魔法敏锐度，但对於较高梯的魔法力有未逮。虽然他们较重视牧师的技巧，但有极少数对秘法或死灵法术略有涉猎。"
D.Strings[117825]="地精 - 地精一向对秘法技艺非常熟练。以拳击来比喻的话，在该量级他们是无人能敌的。他们在祈伦托也占有相当比例。$B$B夜精灵 - 虽然夜精灵把秘法能量当成天谴军团般厌恶，他们在德鲁伊力量的造诣无人可比。"
D.Strings[117826]="德莱尼 - 这个古老的种族替联盟带来了强大巫师与光之技艺的大师。最近，德莱尼在到达卡林多後习得了萨满技巧。$B$B 高等精灵 - 他们的魔法力量非常强大，在魔法敏锐度方面甚至远超过其他任何种族 - 包括人类。在海加尔山战役中，最伟大的英雄们包括了一些高等精灵牧师。"
D.Strings[117827]="老巫师的年监:部落$B$B直到最近几年前，我大部分的部落资讯不过是根据一些谣言或我本人与他们的战斗经验。而藉着祈伦托最近逐渐取得了在部落联盟之间超然中立的立场，关於部落的魔法资讯也随之暴增。 -老巫师。"
D.Strings[117828]="兽人 - 虽然他们的肉体十分强悍，他们同时也拥有不错的魔法能力。兽人的秘法法术能力较差，但是他们有和平萨满技艺的传统，与最近才开始的，对黑暗术士魔法与死灵法术的研究。$B$B牛头人 - 很少有秘法法术的经验，但牛头人对於大地有关的法术很有天份。因为有很多崇拜大自然的部落，许多牛头人都成了萨满。此外，他们最资深德鲁伊的力量能与达纳苏斯的大德鲁伊比拟。"
D.Strings[117829]="食人妖 - 虽然以野蛮着名，他们与魔法的共鸣十分惊人。 《我的祖尔之旅 - 一个深入祖阿曼，祖尔法拉克，与祖尔德拉克的食人妖帝国探险》 - 显示食人妖法师令人吃惊的多元种类，从巫医，暗影牧师到各种可能与德鲁伊有关的奇异动物崇拜。$B$B 不死族 - 不死族在魔法能力上至少能与人类匹敌，甚至更强大。希瓦娜斯手下的被遗忘者们，以可怕的狂热玩弄着法术 。"
D.Strings[117830]="血精灵 - 血精灵自古以来就不断地暴露在充斥魔法能量的环境下，使得魔法在他们身上留下了难以抹灭的痕迹。这些柔软、魔法上瘾的生物，对任何魔法系别来者不拒。最近，血精灵踏上了「血骑士」之路，与圣骑士十分相似。$B$B坦卡 - 与他们的牛头人表兄弟类似，坦卡对大地魔法较为热衷。"
D.Strings[117831]="老巫师的年监: 其他熟悉秘法的种族$B$B魔法并不局限於联盟或部落。许多艾泽拉斯的生物都有能力追求这种奇蹟。 -老巫师"
D.Strings[117832]="纳迦 - 虽然男性纳迦较擅长於近身格斗，女性纳迦却是可怕的法师，对於冰与水的魔法了若指掌。我在这必须强调．他们的远古女王艾萨拉，据说是艾泽拉斯史上最强大的法师。$B$B奈幽虫族 - 只有最强大的奈幽虫族领导者才能施展法术。但是，在被天谴军团屠杀後，许多加入天谴军的奈幽变成了死灵法师。"
D.Strings[117833]="巨魔 - 这些来自德拉诺的流亡者将大部分的注意力放在战士或弓箭之道，但少数选择成为巨魔法师。丘加利，第一位巨魔法师，是个「非常非常强大」的法师(比「非常强大」更加强大)。$B$B萨特 - 这种危险的生物近似於他们的表亲夜精灵，但有着被扭曲的恶魔身躯。身为恶魔魔法大师，萨特非常危险。靠近他们时务必小心。"
D.Strings[117834]="蓝龙 - 这些玛里苟斯的古老子孙是最强大的秘法法师之一。有些蓝龙，例如喜好冒险的卡雷苟斯，对凡人巫师十分友善，而且能成为绝佳的研究拍档。不幸的，最近来自北方的谣言指出一些蓝龙对其他种族的法师变十分仇视。仇视的原因尚未清楚。"
D.Strings[117835]="老巫师的年监:熟悉萨满技艺的种族$B$B我在艾泽拉斯的旅行发现了许多具有萨满传统的种族。这些种族大多居住在海的彼方，拥有先进的自然本位社会组织。 -老巫师"
D.Strings[117836]="野猪人 - 在卡林多还存活的少数野猪人，会施展名为地卜术的魔法，是较为原始的萨满法术。某些受到瘟疫感染的野猪人甚至能在死後施法。$B$B豺狼人 - 豺狼人是一支奇特的种族。我曾因为施展一个达拉然孩童都会的基本法术，而受到赤脊山一个豺狼人族长的欢迎。一整天下来我俩曾是最好的朋友，直到他忘了我的法术并派出他的猎人追杀我。不管怎样，如果他们能集中注意力够久，豺狼人能施展一些元素萨满法术。"
D.Strings[117837]="半人马 - 女性半人马倾向施展一种堕落黑暗的萨满法术。男性半人马很少有魔法能力。$B$B獾狼怪 - 这个类似狼人的团体一开始可能显得原始，但是他们的部落领导通常是强大的萨满。"
D.Strings[117838]="神谕者 - 虽然他们与灌狼怪是世仇，但两者的社会组织十分近似。战士负责打杂，而领导者通常是萨满。$B$B熊怪 - 近来，成为萨满的熊怪有日渐减少的迹象。在自由意志较强烈的熊怪部落，萨满文化也较普及。更有甚者，某些熊怪甚至会基本的变形术，和德鲁伊类似。"
D.Strings[117839]="老巫师的年监: 大陆上的子民$B$B萨满法术并不是唯一以自然为主轴的魔法。许多艾泽拉斯上较低等的种族也能在大地汲取能量施法，但并不是萨满法术。至於他们的魔法能量来源是否与萨满魔法相同，在紫罗兰城塞一直是个热辩议题。- 老巫师"
D.Strings[117840]="巨牙海民 - 这支半人半海象的种族，练习一种与萨满法术惊人相似的魔法。我们的学者尚未解译出巨牙海民所使用魔法的魔力来源。$B$B 狗头人 - 这些低等生物仅仅能施展一些简单的大地法术。我年轻时的探险告诉我某些狗头人会施展相当强力的火球术，不过也仅此而已。"
D.Strings[117841]="枭兽 - 这种长着羽毛的生物有许多别名。这些温和的巨人拥有类似夜精灵的自然德鲁伊能量。$B$B鹰身人 - 这些笑声刺耳的女鸟人能施展强大的元素风暴魔法。我们对他们能量来源的理解十分稀少，因为 1)他们攻击任何人，2)很少有人能理解她们吵杂尖叫的意义，3)没人能忍受她们巢穴的气味。"
D.Strings[117842]="鱼人 - 一直以来，这种怪里怪气的生物，看起来似乎只会施展最基本的魔法。不要被他们低智能的外表骗了。鱼人绝对有能力施展威力十足的大地和水系法术，此外他们的人口也持续的增加。$B$B龙虾人 -  这些长的像龙虾的生物虽然很原始，但拥有水系魔法的潜能。"
D.Strings[117843]="老巫师的年监:不会魔法的生物$B$B不是所有人都适合魔法。这世上有许多缺乏智慧，仅仅依靠本能就能存活上千年的野兽，某些较低等的种族亦是。而有些种族虽然文化十分发达，他们天性不喜欢魔法。理解这些不依赖魔法的种族繁荣的秘诀，对祈伦托来说非常重要。"
D.Strings[117844]="哥布林 - 哥布林不信任魔法。他们只相信自己的工艺技术。和地精不同的是，他们缺乏学习秘法技艺的才能。但也有说法指出，某些哥布林将科技与魔法结合，产生非常有趣的结果。$B$B穴居怪 - 这些生物单纯因为太笨而学不来任何魔法。"
D.Strings[117845]="猛玛象人 - 巨大的猛玛象人几乎不与魔法有任何的共鸣。猛玛象人施法者十分稀少，而且倾向於萨满之路。但我能告诉你第一手资讯，这些大家伙绝不会乖乖束手就擒，而他们的厚重外皮能抵挡最强大的寒冰箭。$B$B维酷人 - 虽然这些北裂境的半巨人大部分不会魔法，有少数被巫妖王训练城死灵法师。我还听到一些关於「符文魔法」的传闻，但我从来没有机会深入研究这个有趣的主题。"
D.Strings[117846]="大领主，$B$B$N成功地带领我们对抗来自天谴岸地的天谴军，并使我们得以开始向寒冰皇冠进军。$B$B泥瓦匠带满了足以兴建正义要塞的材料，这都多亏了$N和$g他:她;在水晶之歌森林的战功。$B$B还剩下最後一个挑战-十字军之巅。我希望从这个最让我们苦恼的所在，开始划下这个时代的终章。$B$B我们等待着您的命令，大人。$B$B愿圣光保护您。$B$B-贾斯塔夫"
D.Strings[117847]="我的主上，$B$B慈悲的王，愿圣光令您刀下留人，并平复您的心跳。请暂缓您对这个死去勇士的判决 - 即使一下子也好 - 并请聆听我的话语。$B$B带着这封信的使者生前曾是联盟的英雄。虽然$g他:她;散发着死亡的恶臭与天谴军的外表，$g他:她;却拥有勇士的灵魂。一个适才返回躯体之中的灵魂。"
D.Strings[117848]="$N代表一支全新团结对抗巫妖王的力量，人称黯刃骑士。没错，我的主上，死亡骑士们转而对抗他们的前任主人。大领主亚历山卓斯·莫格莱尼 - 『灰烬使者』- 的儿子领导着这个组织。他们的目标和我们一致:消灭天谴军团。$B$B我所请求的不是让$N与黯刃骑士加入联盟，而仅仅是您的宽恕与容忍而已。"
D.Strings[117849]="记住，殿下，为了鲜血与荣耀。$B$B您恭敬的，$B$B大领主提里奥·弗丁"
D.Strings[117850]="大酋长，$B$B伟大的战帅，愿圣光令您刀下留人，并平复您的心跳。请暂缓您对这个死去勇士的判决 - 即使一下子也好 - 并请聆听我的话语。$B$B带着这封信的使者生前曾是部落的英雄。虽然$g他:她;散发着死亡的恶臭与天谴军的外表，$g他:她;却拥有勇士的灵魂。一个适才返回躯体之中的灵魂。"
D.Strings[117851]="$N代表一支全新团结对抗巫妖王的力量，人称黯刃骑士。没错，我的主上，死亡骑士们转而对抗他们的前任主人。大领主亚历山卓斯·莫格莱尼 - 『灰烬使者』- 的儿子领导着这个组织。他们的目标和我们一致:消灭天谴军团。$B$B我所请求的不是让$N与黯刃骑士加入部落，而仅仅是您的宽恕与容忍而已。"
D.Strings[117852]="记住，大酋长，我们都是为了鲜血与荣耀。$B$B您恭敬的，$B$B大领主提里奥·弗丁$B$BP.S替我向伊崔格打声招呼，并告诉他我在北裂境需要一个能干的兽人 - 当然，在得到您的允许後。"
D.Strings[117853]="大法师安东尼达斯，祈伦托的大魔导师$B$B名为达拉然的伟大城市再次屹立於此 － 一个赋予圣洁达拉然之子，关於韧性与意志的试炼。$B$B你的牺牲不会毫无价值，最亲爱的朋友。$B$B$B以爱与荣耀之名，$B$B珍娜·普劳德摩尔"
D.Strings[117854]="年复一年，我被关在这个魔法监狱中。今晚，我就要潜逃出去。我备齐了脱逃的一切所需。$B$B<墨水浸水晕开，模糊了信件的这个部分>$B$B为什麽我得在这个鬼地方这麽久?我到底做了什麽才受此惩罚?日复一日，这些问题在我脑海中打转。为什麽有人会落得如此下场?$B$B<墨水浸水晕开，模糊了信件的这个部分>$B$B也许我会在来生了解这个答案。"
D.Strings[117855]="你找到了一样神秘物体的失事残骸。在火焰之後，你可以辨认出一个标记「M:1815212085」。你忍不住好奇这个东西究竟从何而来……"
D.Strings[117856]="匆匆翻阅那些几乎要碎开的书页，只记载了一些在瓦尔甘牧场的生活。季节的变换，庄稼种植与收割的记录，以及孩子的出生与去世。$B$B整个记录在短而破碎的瘟疫描述後嘎然而止。没有一个孩子能长大到完成骑士的训练，就算他们有人在瘟疫後幸存。"
D.Strings[117857]="前半本日志似乎只是库珀先生的生意帐本。手写的一行行数字记录了生产与卖给月溪镇居民的桶数，还有少数顾客来自暴风城。$B$B後半本看起来则像是库珀先生的日记，打算要将家族生意交给他的弟弟。你注意到没有提到任何孩子。"
D.Strings[117858]="第10500日:$B殿堂好安静。空荡荡。$B$B我想造物者要我看守殿堂，但他们从来不肯明确地说，亚夏梵，看守殿堂……或许我也可以看守外面?也许外面不会这麽无聊。就这麽决定 - 我现在负责看守殿堂和外头。下个月开始我就要肩负起新的责任。$B -亚夏梵$B$B第20120日:$B外头比殿堂开阔多了。方便的峭壁和山脉阻隔它。我现在很肯定造物者也一定要我看守这些。我希望他们不会注意到我只在殿堂里待了十年。"
D.Strings[117859]="第1051213日:$B我今天发明了一种新游戏，叫做「踢亡魄」。我今天从要塞前面将它踢到了主要大路上。在明年之前，我要把它踢过河。$B                - 亚夏梵$B$B第2145617日:$B今天来了一些绿色小人。我把他们纳入我的看守责任中。$B                - 亚夏梵$B$B第2145657日:$B小绿人在这里盖了别的建筑。更多的建筑感觉不错。我打算要在这个礼拜跟他讲话，并且感谢他们。$B                -亚夏梵$B$B第2145666日:$B我今天感谢了其中一个小绿人，谢谢他们盖了更多建筑。他告诉我他会带更多人来让我看守 - 更多更多。$B$B我很兴奋能有更多东西来看守。$B                - 亚夏梵"
D.Strings[117860]="<HTML>$B<BODY>$B<P>第一阶段的建造已经完成。韦斯温上将已经下令要我的一小队人马前往北方去建立个立足点。他不肯详细地定下细节，都说他是受到「指引」。"
D.Strings[117861]="这个小地精盯着栏杆外僻静的达拉然庭院。$B$B「阳台这里的视野超棒的。你一定要过来看看!」$B$B马库斯的腿铠咯吱咯吱响的走了过来，他深深的吸了一口气，并随手抓了抓他满胡渣的下巴。$B$B「英雄光临真不赖。而且房间里应该有你感兴趣的东西。」$B$B塔薇迫不及待的冲进房间，只顿了一下就跳上了大床铺。她转过头来用又圆又大的眼睛盯着马库斯，开玩笑地眯了眯眼後，脸上灿烂的笑容换成了诡邪的笑。"
D.Strings[117862]="「想要个玩伴吗?」她口中念念有词并用手划出了一个复杂的召唤仪式，直到她感到一股暖意出现在背後才停了下来。$B$B面无血色的马库斯结结巴巴的抗议着。「我...我想这样不太好吧。」$B$B塔薇疑惑的转过头看是出了什麽问题。一只可怕的地狱犬直挺挺的站着，滴着满地的口水并专注的盯着只穿半副护甲的圣骑士。$B$B「不!我不是这个意思。」她结结巴巴的说着并驱退了那只饥饿的恶魔。「我很抱歉，那不是我擅长的系别...」"
D.Strings[117863]="马库斯握着她的双手并安慰她，「没关系。你擅长的系别是什麽?」$B$B她的头立刻抬起，双眼充满新生命般炯炯有神的同时，暗影能量经由她的手传给了马库斯，让他痛苦的弯下膝盖。$B$B「其实，是痛苦系。」"
D.Strings[117864]="马库斯咬紧牙根的做了个手势，让圣光闪现过全身，恢复了他的体力。$B$B塔薇紧张地看着他立起身子，直到身影将她吞没。他把手向前伸，将公正能量的波动穿透她全身。她翻起了白眼，颤抖了数秒才逐渐回过神来。$B$B「我最近选择了...惩戒之道。」$B$B她的脸上恢复了淘气的嘻笑，「那看来应该会蛮有趣的。」$B$B<剩下的页数必须要等级99时才能阅读。>"
D.Strings[117865]="寇勒医生，$B$B黑骑士还有用处。从银白联赛场地取回他的遗体并用你的技术复活他。我们将使用十字军的力量及他们的跟随者来对付他们自己。$B$B使用那些囚犯的灵魂来活化我的仆人。抓住被那些跟随者称做『鲁莽』的库尔，把他献祭给你的祭坛。他的灵魂将给予黑骑士恐怖的力量及能力。然後，把黑骑士送来给我。"
D.Strings[117866]="结合了五大龙群的意志来铸造棱彩之剑确实是很罕见的。而这些武器中最卓越的就是奎尔赛拉与奎尔德拉这一对剑。$B$B在龙后雅立史卓莎的智慧下，她将这两把剑分别送给了艾泽拉斯的精灵族。奎尔赛拉由一位英勇的卡多雷战士所持有，而奎尔德拉则交付给奎尔多雷的勇士。$B$B两把剑都在不同的持有者手中流传，让它的魔法来强化持剑者的力量……"
D.Strings[117867]="你必须前往白银领区的最上层会见秘法师泰巴林。他会将一本弥足珍贵的书籍托付给你。请谨慎行事，同时用你的生命来守护这本书。尽快将它带到奎尔德拉之眠交给卡拉迪斯·亮矛吧。"
D.Strings[117868]="你必须前往下流畜生酒店会见博学者哈索瑞尔。他会将一本弥足珍贵的书籍托付给你。请谨慎行事，同时用你的生命来守护这本书。尽快将它带到奎尔德拉之眠交给米拉连恩·日炎吧。"
D.Strings[117869]="第214586日:$B小绿人带了更多人来，他们彼此指着，然後开始打了起来!$B$B我缩减我的看守职责，躲回殿堂中以策安全，但我带了很多他们的小东西回来，免得我这段时间太无聊。$B                - 亚夏梵$B$B第214620日:$B情况越来越糟。我不确定造物者希望我怎麽做。我试着在殿堂中待着，那些暴力的家伙一天闯进来好几次。他们拿走了我的小东西。$B                - 亚夏梵"
D.Strings[117870]="第2147021日:$B我的兄弟们回来了!结果是他们睡在其他关闭的殿堂中。$B$B我有点不高兴他们放我一个人做所有的看守工作，不过我还是跟他们分享了我那些闪亮亮的小东西，毕竟我实在厌倦了一个人还有老是被攻击。$B                -亚夏梵$B$B第2147060日:$B暴力的小人开始攻击我的兄弟们，真糟糕。不过他们现在很少来烦我了，这是不糟糕的。$B$B我想那些家伙大概是想要我送给他们的闪亮小东西。我感觉好有罪恶感。$B                - 亚夏梵"
D.Strings[117871]="献给在冰冻荒原与天谴军团作战而丧生的勇士们。"
D.Strings[117872]="当火焰吞噬艾泽拉斯，你会在哪里?$B$B我们知道没有人喜欢老是想着逼近的末日，但是考虑之後的发展仍是必须的。$B$B我们的贤者们预言了末日的来临，只有做好准备的人才能活下来。我们可以帮你在清洗世界败类的狂野火焰中生存下来。也该是寻找心灵宁静的时候了，不是吗?"
D.Strings[117873]="你一定听过「好景不常在」这句话，而你在艾泽拉斯的生活也是如此。再过不久，当元素重返来夺回它们与生俱来的权利，整个世界就会陷入混乱。$B$B但是你不用害怕，因为在这种痛苦的时刻，你不是非死不可。我们可以帮你昇华到新的生活方式，超越死亡，超越恐惧，甚至超越凡人无能为力的境况。今天就加入我们吧。"
D.Strings[117874]="我们活在动荡的年代。战争、侵略和饥荒横扫了整个世界，但真正的考验尚未来临：艾泽拉斯的终结。$B$B你要怎样面对你珍视的一切被摧毁?答案是你不需要。带着你的朋友和家庭来我们的聚会并跟着我们一起学习如何在末日中生存下来。"
D.Strings[117875]="<还有一页看得清字的，但是这本书剩下的部分实在太破旧了……>\n今天有客人。麦迪文来找艾里克斯讨论一些机密事宜，然后艾里克斯带他在这里逛了逛。\n\n麦迪文对艾里克斯的计划抱有很大的兴趣，主动提出帮忙。艾里克斯提到了在设置结界时现实的脆弱性，麦迪文说会研究一下，并鼓励艾里克斯尝试在恶魔的世界进行仪式。\n\n奇怪的是，有那么一小会儿，我看到麦迪文在盯着结界的时候，脸上的笑容有点诡异。这让我……很不安。不过他马上又变得严肃、友好，所以大概是我想太多了吧。"
D.Strings[117876]="虽然议会很庆幸巴拉杜尔不能进入艾泽拉斯，但是这也导致他的攻击几乎无法化解。议会所有的法师都收到了警告，小心他的捕猎行为。"
D.Strings[117877]="<这本书上的字几乎无法辨识……>\n今天的实验很顺利。在结界里，卡拉赞扭曲现实的腐化现象似乎完全消失了。艾里克斯非常高兴，虽然因为法力蛭的缘故，做一场实验要花很久的时间。设置结界的时候似乎会吸引大批的法力蛭。"
D.Strings[117878]="真是祸从天降！艾里克斯和他的徒弟全都死了！剩下的议会成员不想重蹈覆辙，正在销毁艾里克斯和他的仪式的全部记录。戴奥因为卷入其中，也被打发走了。\n\n他们把这件事看成是一场事故，一场失败的实验，但是还有其他成员去世，所以我怀疑这其实是谋杀。巴拉杜尔极其擅长发现法师的弱点。实在是过于擅长了。我一定要展开调查。\n\n——K"
D.Strings[117879]="虽然情报并不丰富，但是很显然，提瑞斯法议会的成功已经引起了一些更高层的恶魔领主的注意。\n\n如今，已经出现了好几次法师被恶魔袭击，甚至被偷袭的情况，这些恶魔是听命于一个叫巴拉杜尔的强悍艾瑞达。议会的很多计划也因此受挫。如果是力量非凡的咒术师或者大法师，巴拉杜尔会亲自参战，用某种方式在现实中制造裂隙，然后强迫或者说服这些法师进入裂隙。\n\n在一个极其罕见的个例里，有人活着从那里回来了。他看到巴拉杜尔玩弄着死去猎物的武器，把它们作为战利品，耀武扬威。\n\n"
D.Strings[117880]="<由于年代久远，这本书的大部分内容都难以辨认>\n……所以这就是他的命运，注定要被流放到扭曲虚空，再也无法回到艾泽拉斯。就连他的亲生儿子米尔豪斯，最终也背叛了他。不过在我看来，米尔豪斯这么做，并不是为了达拉然和艾泽拉斯的命运着想。\n\n一想到玛格努斯有办法逃出我们制造的魔力流放监狱，我就觉得荒谬透顶。但是我总觉得有些事情不太对劲。可是，我们别无选择。玛格努斯的问题相当罕见：他死了带来的麻烦比他活着更严重。\n\n<还有一些可以辨认的笔记，提到了一个叫幽幻区的东西。它是某个维度里的一个监狱空间，会永远在扭曲虚空里飘荡，里面的犯人可以看到外面，但是永远逃不出去。>"
D.Strings[117881]="这个指南针十分老旧，由于长期的使用而变得破损不堪。\n\n它好像已经坏掉了——指针毫无规律地改变方向，但就是无法指向正北方。"
D.Strings[117882]="箱子里装着各种神奇的小玩意。\n\n仔细检查之后，你发现这些“圣物”不过只是些高仿的赝品。"
D.Strings[117883]="我个人和艾德温·范克里夫相处了很久，根据我对他的了解，这么说吧，与他为敌不是那么容易的。要知道，他是我儿时的伙伴，是我亲自训练他的，因为我以为有一天他会和我并肩工作。如果范克里夫就是迪菲亚兄弟会的首脑，那么只能希望圣光怜悯我们的灵魂了。$B$B马迪亚斯·肖尔大师$B暴风城刺客公会"
D.Strings[117884]="注意：\n汉化人：\n\r==============================\n\r筱免點子&rpg团队的其他成员。\n\r\n"
D.Strings[117885]="安东尼·雷·斯塔克$B$B1961——2005"
D.Strings[117886]="1、如果你不喜欢它的药效，请将计量翻倍或减半。$B$B2、如果你的毒药无法发挥出你想要的功效，那说明你想的太美好，现实很残酷。$B$B3、原型！原型！原型！（侏儒是很好的实验对象。）$B$B4、毒药虽好，可使用容易，结束难。$B$B5、简单的成分混合在一起就能创造出无数有趣的东西。"
D.Strings[117887]="<笔记很难辨认，但是你可以根据粉红色的引用作为参考……>"
D.Strings[117888]="爸爸又让我照顾奥贝斯了。我想他应该想看到我被她撕成碎片吧。她不像其他人那样喜欢我又不是我的错——我不过是吃了一次为她准备的苹果而已。我甚至都不知道她是怎么知道这件事的。"
D.Strings[117889]="巴古多夫满怀着希望刻苦学习。他在同学们面前一口气喝下了好多好多法力药水，以为这样可以提高他的魔法技能。但唯一的结果，却是他好多次在重要的祈祷仪式上打嗝，或者把同学的长袍烧着，又或者把老师的胡子变成羊毛。"
D.Strings[117890]="在巴古多夫第一次参加考试的时候，考官要求他施放一个冰甲术。当他开始施法的时候，其他学生都很害怕地蜷缩在座位上。一层蓝色的迷雾笼罩着年轻的巴古多夫，看起来他好像成功了。但是很快，他就开始发抖和打喷嚏，大家终于明白了，原来他对自己施放了霜寒刺骨。"
D.Strings[117891]="有一天，巴古多夫在花园里散步，心里想着他是不是根本不是一块当法师的料。他看着在周围玩耍的小孩子，回忆起了自己的梦想：成为一名强大的施法者。“没错，”他心想，“我一定可以成功的。我只需要更加刻苦勤奋！”于是巴古多夫开始寻找可供练习魔法的目标，并注意到了一棵不太寻常的树。巴古多夫鼓起勇气，对这棵树施放了一个法术，然后闭上眼睛，不敢去看这个法术的结果。"
D.Strings[117892]="最后他终于睁开眼睛，哎呀！那棵树变成了一位漂亮的暗夜精灵。“成功啦？”巴古多夫大声喊道，“变形术成功啦！我果然还是可以当法师的呀！”$B$B暗夜精灵感到很迷惑，但是随即就明白了是怎么回事。她对巴古多夫温柔地笑了笑，说道：“我是一名德鲁伊，孩子。我们可以随意变成别的模样。”"
D.Strings[117893]="巴古多夫的脸红得像苹果一样，急忙转身走开，却一不小心踩到了自己的长袍，在大街上摔了个跟头。路上的其他人都大笑起来，巴古多夫急忙把自己的尖帽子戴好，低着头羞愧地回到了自己的宿舍。"
D.Strings[117894]="那个暗夜精灵在原地站了一会儿，心里想着刚才那个男孩子的事情。当她准备离开的时候，被脚下的某样东西绊了一下，差点摔倒。她低头一看，在刚才还空无一物的地上，不知什么时候出现了一簇闪闪发光的魔皇草，它的花瓣正在慢慢伸展开来，绽放成为一朵美丽的鲜花。她惊讶地看着这朵花，然后恍然大悟地抬起头，向巴古多夫离开的方向望去，但是那位年轻的法师已经不见踪影了。"
D.Strings[117895]="在12岁时，安东尼达斯发表了题为《将时光回溯旅行理论应用于精确魔法实践的分枝法》的论文，并因此获得了肯瑞托至高智慧绶带。他是该奖项有史以来最年轻的获得者。随后，管理议会批准他进入肯瑞托高级研究及启蒙学院，他也是有史以来获得官方批准的最年轻者。"
D.Strings[117896]="随着安东尼达斯继续成长，他继续学习并精进自己的魔法技艺。安东尼达斯在防御魔法领域的过人天赋和智慧，使得他成为了六人议会的理想候选人，而他也最终顺利进入了六人议会。安东尼达斯不仅非常睿智和公正，还拥有渊博的知识。他很快就成为了达拉然最有影响力的人物。"
D.Strings[117897]="在第二次战争之前，艾泽拉斯各国的领袖聚集在洛丹伦，讨论兽人入侵的问题。大法师安东尼达斯代表六人议会出席了此次峰会，并明确了达拉然效忠联盟的立场。他还关注着极有才华的年轻法师卡德加的状况，后者在第一次战争期间曾是麦迪文的学徒。第二次战争结束后，安东尼达斯将卡德加晋升为大法师，并任命他为进入黑暗之门、调查德拉诺的指挥官。"
D.Strings[117898]="第二次战争之后，安东尼达斯调查了兽人的异常虚弱状态，并基于研究成果发表了一系列论文：《战争的因果：对兽人虚弱状态的全面研究》、《兽人习俗、社会学和心理学行为在第二次战争前后的对比》、《对邪能魔法的系统及历史的实验研究，以及它们与兽人种族的关联》。"
D.Strings[117899]="这些报告并没有得出确定的结论。安东尼达斯自己也曾表示，为兽人寻找医治此种疾病的途径几乎是不可能的。他最后指出：兽人只能通过精神方面的途径来回归健康的生活方式。"
D.Strings[117900]="第五条：禁止对任何正在穿越传送门的生物施放变形术——这样做将无一例外地引发爆炸事件。在《传送门纯粹理性批判：关于正确使用传送门的备忘录》中亦涵盖了此条法规。"
D.Strings[117901]="扭曲虚空是虚无的广袤空间，但这绝不是将其视为垃圾场的理由！你们所掌握的传送门以及传送法术象征着特权与责任，如果不小心将午餐的残渣带进了传送门，则很可能在艾泽拉斯世界引发灾难性的后果！请在跨越传送门后检查你随身携带的物品，如有遗失，立即向肯瑞托议会汇报。关于传送门的使用守则，请参阅最新版本的《传送门备忘录－正确使用传送门的守则》。"
D.Strings[117902]="倘若这种恶劣的行径愈演愈烈，我将不得不颁布法令，要求所有使用传送门的旅客在启程前取下他们的武器装备以及私人卫生用品。如果再让我发现自己的讲稿漂浮在一堆垃圾中，我会亲自将所有学徒的脑袋变成纸糊的帽子！$B$B——大法师安斯雷姆·鲁因"
D.Strings[117903]="如果你不喜欢喧闹的场所，可以选择达拉然中部的“霍克噗克”。这家露天旅店很好找，你可以点一份便餐，和邻桌的朋友分享旅途的见闻，享受舒适惬意的氛围。神情疲惫的奥术师学徒是霍克噗克的常客，因此你可以在这里欣赏到自动烹制的食物，而且它们都相当美味哦！"
D.Strings[117904]="如果你只想要一张床和一杯酒，那就去肮脏的野兽！昏暗的吧台散发着阵阵恶臭，形形色色的可疑人物在这里频繁进出。菜单上的推荐美味是咸奶酪；客房里脏得厉害，恐怕得用一打魔法扫帚和水桶才能将床铺打扫干净。真是再适合部落的家伙们不过了！"
D.Strings[117905]="作为被遗忘者，我们同巫妖王作战，我们同联盟作战……某些时候我们还得和部落的盟友们争斗。$B我们种族人数很少，我们面临着极大的困难……但我们必将生存下来并取得胜利。$B$B作为一名猎人，你会在不远的将来做这些事情，拿着弓，身边有你的动物伙伴。$B你的力量并非来自玄妙的巫术和虚无缥缈的力量，而是来自于你在陆地上生存的能力。$B$B猎人之路就在你的面前。$B$B从我这里开始，你的训练导师。$B$B它会在哪里结束……我们尚未知晓。"
D.Strings[117906]="需要大芒果文本"
D.Strings[117907]="你好，威廉，$B$B距離上次我們見面已經過了好幾年，但是我相信你和你的兄弟都一切安好，你的藥劑生意也一定很興旺。$B$B威廉，現在我需要你的幫助。長話短說吧，我的孫子湯米·喬與年輕的梅貝爾·馬科倫相愛了。他們互相愛慕……但是我們兩個家族之間已經明爭暗鬥了好幾年。"
D.Strings[117908]="他們有一個龐大的地下網路。斯托曼，這個網路比你所知道的更為龐大。從藏寶海灣到暴風要塞都有他們的勢力。也許你是個勇敢的聖騎士，不過如果你以為，憑你的一己之力就能阻止他們，那你就太傻了。他們正在研究一種大規模殺傷性武器。總之，那些石工的看家本領就是如何製造大傢伙。你不會以為他們的興趣只是南瓜田和葡萄園吧?我已經報答了你為我提供的幫助。現在，離我遠點吧!$B$B─W"
D.Strings[117909]="夜色鎮的鎮長埃伯洛克大人，您好。恐怕我有個壞消息要捎給夜色鎮。$B$B您知道，我是一個創造天才。我欺騙了給您送信的這個蠢貨，騙他幫我完成了我最強大而恐怖的創造─一個用血肉和扭曲的金屬製成的惡魔!當您讀著這封信的時候，它就在我簡陋的屋子外面，張牙舞爪，隨時準備血洗夜色鎮。$B$B您很快就可以看見它了。$B$B- 藏屍者"
D.Strings[117910]="我帶著隊伍繼續往海邊走去，希望在那裡的海岸線旁找到某個可以避開迅猛龍的地方。但是在匆忙之中，我們跑到了一處危險的高地，這是個可怕的錯誤，全都是我的錯。我們停在了一個陡峭的懸崖邊，而那些迅猛龍距離我們僅有幾步之遙。"
D.Strings[117911]="第一天和我們預想的完全一樣。我們大部分時間都忙於為建立營地做一些必要安排。我在一條淡水河的入口處找到了一個理想的駐紮點。根據旁邊被廢棄的古老碼頭判斷，這個地方曾經有人住過，不過只有時間才能說明這裡究竟住過什麼人。"
D.Strings[117912]="那是一隻雄性的荊棘谷猛虎。我還沒來得及拿起槍，艾爾加丁已經拉開他的弩，向那頭野獸射出了箭矢。這一下未能射中要害，不過還是重重地射入了猛虎的左腹。老虎想要逃跑，但是它傷得太重，只蹣跚走了幾步就被巴尼爾的斧頭擊中，倒地身亡。"
D.Strings[117913]="艾耶克和艾爾加丁爵士很想知道如何有效地使用矮人步槍狩獵。所以我讓這兩個對此一無所知的人類把他們的弓箭留在營地中，然後讓巴尼爾給他們裝備了一些鐵爐堡最好的武器。"
D.Strings[117914]="過了幾個星期，我們的豹皮和虎皮儲備已經相當充足了。於是我決定將探險隊的注意力轉向一個新的挑戰:迅猛龍。$B$B隊伍中的兩個人類雖然十分感激我和巴尼爾對他們進行的訓練，不過他們還是決定不使用我們提供的火槍去打獵。艾耶克更喜歡她那調校完美的強弓，而艾爾加丁爵士離開營地的時候總是拿著他的弩。"
D.Strings[117915]="但是我還沒有時間體會這次獵殺的愉悅，就赫然發現山頂上出現了幾個影子─就在可憐的巴尼爾的正上方。$B$B「快跑，巴尼爾!」我大叫道。艾耶克、艾爾加丁和我立刻向追逐巴尼爾的迅猛龍射擊，一時間子彈和箭矢亂飛，混亂之中，我們當中的某人還射殺了一隻迅猛龍。"
D.Strings[117916]="突然之間，奇蹟發生了。我們聽見一隻白虎清晰而可怕的吼聲從對面傳來。雖然迅猛龍數量眾多，但它們一聽到叫聲便立刻四散逃竄。那隻老虎像一道白色閃電般從我們身前跑過，撲向一隻迅猛龍。不需要任何命令和溝通，我們四個人都明白:這正是逃跑的最佳時機。"
D.Strings[117917]="完成了這一步，我們就可以開始下一階段的計畫。在擁有了自己的國家和這個地區的前沿基地之後，我們就可以為第三次入侵作準備了。$B$B不久，軍團的首領將會表彰我們，讓從天而降的烈焰吞噬整個世界!"
D.Strings[117918]="血帆命令$B$B親愛的水手們，請仔細看好這篇命令中的內容，因為我們在藏寶海灣發財的機會只有一次。$B$B我已經派鄧肯守在北邊，並告訴他等待行動的信號。$B$B達姆希的好運號將停靠在南邊的海角旁等待補給命令。小個子的斯蒂沃特船長會讓他的船員做好運送戰利品的準備。我相信布魯圖斯那個蠢貨會是我們最大的麻煩。"
D.Strings[117919]="於是他到處遊蕩、尋找。而他還是沒有找回那隻手臂。於是他一邊走一邊咒罵怒號著。$B$B但是格里雷克已經很久沒有聽從神靈的教誨，他們因此而憤怒，不再理會他的咒罵。$B$B格里雷克的命運就是這樣，命運讓他不斷遊蕩，讓他缺少一隻手臂。"
D.Strings[117920]="科爾寶石:從我所知道的一些傳說來看，這種寶石是法師用來儲存能量所用的，這可以極大地增強他們的力量。我曾經幫助過一個名叫桑迪斯·織風的夜精靈，他可以告訴你更多有關寶石的資訊，只要你和他提到我，他就一定會幫忙的。我相信這些寶石中一定蘊藏了可以幫你鑄造武器的力量。$B$B我和桑迪斯上次見面的時候，他住在黑海岸的奧伯丁，那裡是夜精靈的家園，周圍都是被污染的森林。"
D.Strings[117921]="<HTML>$B<BODY>$B<H1 align=\"center\">$B東部水晶塔圖表$B"
D.Strings[117922]="<這個頁面上寫滿了古代精靈文字。>$B$B這些書頁中記述了在製作次級秘紋的過程中所發生的事件。$B$B願我的敵人永遠無法得到這些資料。$B$B願我有生之年能夠重見潔白的月光照耀奎爾薩拉斯。$B$B願我能以凱爾薩斯之名奮戰。$B$B願我能為伊利丹的榮耀而戰死。$B$B- 卡里爾·溫薩魯斯"
D.Strings[117923]="多加爾·石眉$B血色十字軍戰士 $B紅色洞穴的領主$B失蹤於奧特蘭克山脈"
D.Strings[117924]="A:$b$b我們從羅德隆派來的使者不久之後就會與你會面。一旦我們找到了進行會談的合適地點，就會及時通知你。$b$b- G"
D.Strings[117925]="根據高級執行官哈德瑞克的命令，以下物品是維持瑟伯切爾庫存的必需品:$B$B12把長劍$B9把匕首$B8面圓盾$B15把斧頭$B1000支箭$B$B這些物品必須完全備齊，這是黑暗女王的直接命令，負責執行此命令者將受到她的關注，而任何違背這一命令的行為都將被認為是違背黑暗女王的意願。"
D.Strings[117926]="<HTML>$B<BODY>$B<H1 align=\"center\">部落軍官軍階"
D.Strings[117927]="部落受人尊敬的領導者，$B$B我 - 洛索瑪·塞隆，奎爾薩拉斯地區統治者 - 非常榮幸的宣佈我們所知道的達克汗·崔希爾，天譴軍團的指揮官陣亡了。$B$B達克汗在我們土地上的立足點是由辛多雷種族的評論家在先前無數次的協商中所建立的。我們希望這個事件能平撫所有你心裡可能有的異議。$B$B<署名>洛索瑪·塞隆"
D.Strings[117928]="<在這張嚴重燒毀的頁面上已經沒有任何可以辨識的字跡了。>"
